class Position:
    symbol: str
    position_side: str
    entry_price: float
    mark_price: float
    positionAmt: float
    initial_quantity: float
    gain: float
    max_gain: float
    prev_gain: float
    max_quantity: float
    last_augmentation_amount: float
    last_augmentation_price: float
    last_augmentation_time: Optional[datetime]
    last_reduction_amount: float
    last_reduction_price: float
    last_reduction_time: Optional[datetime]
    max_positionSize: float
    opened_at: Optional[datetime]
    last_updated: Optional[datetime]
    last_signal: str
    realized_pnl: float = 0.0
    unrealized_pnl_USD: float = 0.0
    was_reentered: bool = False
    was_reduced: bool = False
    is_reduced: bool = False
    reduced_at: Optional[datetime] = None
    prev_gain_last_updated: Optional[datetime] = None
    augment_reason: str = ""
    reduction_reason: str = ""
    mark_price_last_updated: Optional[datetime] = None
    @classmethod

    def from_dict(cls, data: Dict[str, Any]) -> "Position":
        if not isinstance(data, dict): raise TypeError(f"Position.from_dict() requires a dict, got {type(data).__name__}")
        data = _convert_timestamp_strings(data)

        def safe_float(x):
            if x is None: return 0.0
            if isinstance(x, (int, float, Decimal)): return float(x)
            if isinstance(x, str):
                s = x.strip()
                if s == "": return 0.0
                s = s.replace(", ", "")
                try: return float(Decimal(s))
                except Exception: return 0.0
            if isinstance(x, dict):
                for k in ("amount", "qty", "positionAmt", "value"):
                    v = x.get(k)
                    if v is not None: return safe_float(v)
            try: return float(x)
            except (TypeError, ValueError): return 0.0

        def safe_time(x):
            if isinstance(x, datetime): return x.replace(tzinfo=timezone.utc) if x.tzinfo is None else x
            if isinstance(x, str):
                try: return isoparse(x) if isinstance(isoparse(x), datetime) else pd.to_datetime(x, utc=True).to_pydatetime()
                except (ValueError, TypeError):
                    try: return pd.to_datetime(x, utc=True).to_pydatetime()
                    except (ValueError, TypeError): return None
            return None
        return cls( symbol=str(data.get("symbol", "")), position_side=str(data.get("position_side", "")), entry_price=safe_float(data.get("entry_price")), mark_price=safe_float(data.get("mark_price")), positionAmt=safe_float(data.get("positionAmt")), initial_quantity=safe_float(data.get("initial_quantity")), gain=safe_float(data.get("gain")), max_gain=safe_float(data.get("max_gain")), prev_gain=safe_float(data.get("prev_gain")), max_quantity=safe_float(data.get("max_quantity")), last_augmentation_amount=safe_float(data.get("last_augmentation_amount")), last_augmentation_price=safe_float(data.get("last_augmentation_price")), last_augmentation_time=safe_time(data.get("last_augmentation_time")), last_reduction_amount=safe_float(data.get("last_reduction_amount")), last_reduction_price=safe_float(data.get("last_reduction_price")), last_reduction_time=safe_time(data.get("last_reduction_time")), max_positionSize=safe_float(data.get("max_positionSize")), opened_at=safe_time(data.get("opened_at")), last_updated=safe_time(data.get("last_updated")), last_signal=str(data.get("last_signal", "")), realized_pnl=safe_float(data.get("realized_pnl")), unrealized_pnl_USD=safe_float(data.get("unrealized_pnl_USD")), was_reentered=data.get("was_reentered", False), was_reduced=data.get("was_reduced", False), is_reduced=data.get("is_reduced", False), reduced_at=safe_time(data.get("reduced_at")), prev_gain_last_updated=safe_time(data.get("prev_gain_last_updated")), augment_reason=str(data.get("augment_reason", data.get("reason", ""))), reduction_reason=str(data.get("reduction_reason", data.get("reason", ""))), mark_price_last_updated=safe_time(data.get("mark_price_last_updated")), )

    def to_dict(self) -> Dict[str, Any]:
        result = asdict(self)
        for key, value in result.items():
            if isinstance(value, datetime): result[key] = value.strftime('%Y-%m-%dT%H:%M:%S.%fZ')
            elif value is None: result[key] = None
        return result

def _convert_timestamp_strings(data: Any) -> Any:
    """Recursively convert all timestamp strings in dict/list to datetime objects - CRITICAL for all JSON loads"""
    if isinstance(data, dict):
        result = {}
        for key, value in data.items():
            if isinstance(value, str) and any(ts_key in key.lower() for ts_key in ['time', 'timestamp', 'updated', 'at', 'date']):
                try:
                    if 'T' in value and ('Z' in value or '+' in value or value.count('-') >= 2):
                        parsed = isoparse(value)
                        result[key] = parsed.replace(tzinfo=timezone.utc) if parsed.tzinfo is None else parsed
                    else:
                        result[key] = value
                except (ValueError, TypeError):
                    try:
                        parsed = pd.to_datetime(value, utc=True).to_pydatetime()
                        result[key] = parsed.replace(tzinfo=timezone.utc) if parsed.tzinfo is None else parsed
                    except (ValueError, TypeError):
                        result[key] = value
            elif isinstance(value, (dict, list)):
                result[key] = _convert_timestamp_strings(value)
            else:
                result[key] = value
        return result
    elif isinstance(data, list):
        return [_convert_timestamp_strings(item) for item in data]
    return data

class DummyLock:
    async def __aenter__(self) -> "DummyLock": return self
    async def __aexit__(self, t, v, tb) -> bool: return False
    async def acquire(self): pass
    def release(self): pass
    def locked(self): return False

    def locked(self): return False

class BreakoutHunter:
    """24/7 SMA200 breakout scanner. Runs every 2 min via cron or main loop.
    Scans ALL Binance futures for symbols breaking above/below SMA200.
    Sizes by outperformance vs BTC. Trails max gain for exit.
    Uses fin account. Adds new symbols to symbols.json automatically."""
    ACCOUNT = "fin"
    STATE_FILE = config.BASE_PATH / "data" / "breakout_hunter_state.json"
    LOCK_FILE = config.BASE_PATH / "data" / ".breakout_hunter_lock"
    MAX_POSITIONS = 8; MIN_SIZE_USD = 15.0; MAX_SIZE_USD = 150.0; TRAIL_PCT = 0.4
    _instance = None
    @classmethod
    def get(cls):
        if cls._instance is None: cls._instance = cls()
        return cls._instance
    def __init__(self):
        self._state = self._load_state()
        self._last_run = 0
    def _load_state(self):
        try: return json.loads(self.STATE_FILE.read_text()) if self.STATE_FILE.exists() else {"positions": {}, "btc_sma200_dist": 0}
        except: return {"positions": {}, "btc_sma200_dist": 0}
    def _save_state(self):
        self.STATE_FILE.parent.mkdir(parents=True, exist_ok=True)
        self.STATE_FILE.write_text(json.dumps(self._state, indent=2, default=str))
    async def run(self, trade_manager=None):
        """Main entry — call every 2 min. Scans breakouts, manages positions."""
        now = time.time()
        if now - self._last_run < 110: return  # Cooldown 110s
        self._last_run = now
        try:
            import aiohttp
            async with aiohttp.ClientSession() as session:
                tickers = await self._get_tickers(session)
                if not tickers: return
                await self._manage_exits(tickers, trade_manager)
                breakouts = await self._scan(session, tickers)
                cur = len(self._state.get("positions", {}))
                entered = 0
                for bo in breakouts:
                    if cur + entered >= self.MAX_POSITIONS: break
                    k = f"{bo['sym']}_{bo['side']}"
                    opp = f"{bo['sym']}_{'SHORT' if bo['side'] == 'LONG' else 'LONG'}"
                    if k in self._state.get("positions", {}) or opp in self._state.get("positions", {}): continue
                    logger.info(f"[BREAKOUT_HUNTER] 🎯 {bo['sym']} {bo['side']} dist={bo['dist']:+.1f}% 24h={bo['chg']:+.1f}% sz={bo['sz']:.1f}x")
                    if await self._enter(session, bo, trade_manager): entered += 1
                if entered: logger.warning(f"[BREAKOUT_HUNTER] Entered {entered} new. Total: {len(self._state.get('positions', {}))}")
            self._save_state()
        except Exception as e:
            logger.error(f"[BREAKOUT_HUNTER] Error: {e}")
    async def _get_tickers(self, session):
        try:
            async with session.get("https://fapi.binance.com/fapi/v1/ticker/24hr") as r:
                if r.status != 200: return {}
                data = await r.json()
                return {d["symbol"]: {"price": float(d["lastPrice"]), "vol": float(d["quoteVolume"]), "chg": float(d["priceChangePercent"])} for d in data if d["symbol"].endswith("USDT") and float(d["lastPrice"]) > 0}
        except: return {}
    async def _get_closes(self, session, sym, limit=210):
        try:
            async with session.get(f"https://fapi.binance.com/fapi/v1/klines?symbol={sym}&interval=1h&limit={limit}") as r:
                if r.status != 200: return []
                return [float(k[4]) for k in await r.json()]
        except: return []
    async def _scan(self, session, tickers):
        btc_c = await self._get_closes(session, "BTCUSDT")
        btc_sma = sum(btc_c[-200:]) / 200 if len(btc_c) >= 200 else 0
        btc_p = tickers.get("BTCUSDT", {}).get("price", 0)
        btc_dist = ((btc_p - btc_sma) / btc_sma * 100) if btc_sma > 0 else 0
        self._state["btc_sma200_dist"] = round(btc_dist, 2)
        # Load P&D blacklist (maintained by ez_breakout_hunter.py cron agent)
        _bl_file = config.BASE_PATH / "data" / "pump_dump_blacklist.json"
        _blacklisted = set()
        try:
            if _bl_file.exists(): _blacklisted = set(json.loads(_bl_file.read_text()).get("symbols", {}).keys())
        except: pass
        cands = sorted([(s, t) for s, t in tickers.items() if t["vol"] > 5_000_000 and s != "BTCUSDT" and s not in _blacklisted], key=lambda x: abs(x[1]["chg"]), reverse=True)[:60]
        bos = []
        for sym, t in cands:
            try:
                c = await self._get_closes(session, sym)
                if len(c) < 201: continue
                sma200 = sum(c[-200:]) / 200
                if sma200 <= 0: continue
                p = t["price"]; dist = (p - sma200) / sma200 * 100; prev_dist = (c[-2] - sma200) / sma200 * 100
                if 0 < dist < 10 and (prev_dist <= 0 or (prev_dist < 2 and dist > prev_dist + 0.5)):
                    sz = max(0.5, min(3.0, 1.0 + (dist - btc_dist) / 8))
                    bos.append({"sym": sym, "side": "LONG", "p": p, "sma": sma200, "dist": round(dist, 2), "chg": t["chg"], "outperf": round(dist - btc_dist, 2), "sz": round(sz, 2)})
                elif -10 < dist < 0 and (prev_dist >= 0 or (prev_dist > -2 and dist < prev_dist - 0.5)):
                    sz = max(0.5, min(3.0, 1.0 + (btc_dist - dist) / 8))
                    bos.append({"sym": sym, "side": "SHORT", "p": p, "sma": sma200, "dist": round(dist, 2), "chg": t["chg"], "underperf": round(btc_dist - dist, 2), "sz": round(sz, 2)})
                await asyncio.sleep(0.03)
            except: continue
        bos.sort(key=lambda x: abs(x.get("outperf", 0) or x.get("underperf", 0)), reverse=True)
        return bos
    async def _enter(self, session, bo, trade_manager=None):
        try:
            from utils import load_environment_from_gpg
            env = load_environment_from_gpg()
            import ccxt.async_support as ccxt
            ex = ccxt.binance({"apiKey": env.get(f"BINANCE_API_KEY_{self.ACCOUNT.upper()}"), "secret": env.get(f"BINANCE_API_SECRET_{self.ACCOUNT.upper()}"), "options": {"defaultType": "future"}})
            usd = min(self.MAX_SIZE_USD, self.MIN_SIZE_USD * bo["sz"])
            await ex.load_markets()
            if bo["sym"] not in ex.markets: await ex.close(); return False
            qty = float(ex.amount_to_precision(bo["sym"], usd / bo["p"]))
            if qty <= 0: await ex.close(); return False
            o = await ex.create_market_order(bo["sym"], "buy" if bo["side"] == "LONG" else "sell", qty)
            logger.warning(f"[BREAKOUT_HUNTER] ✅ ENTRY {bo['sym']} {bo['side']} qty={qty} ${usd:.0f} id={o.get('id','?')}")
            self._state["positions"][f"{bo['sym']}_{bo['side']}"] = {"sym": bo["sym"], "side": bo["side"], "ep": bo["p"], "qty": qty, "ts": datetime.now(timezone.utc).isoformat(), "max_g": 0.0, "sz": bo["sz"]}
            await ex.close()
            return True
        except Exception as e:
            logger.error(f"[BREAKOUT_HUNTER] ❌ {bo['sym']}: {e}"); return False
    async def _manage_exits(self, tickers, trade_manager=None):
        for key, pos in list(self._state.get("positions", {}).items()):
            t = tickers.get(pos["sym"])
            if not t: continue
            p = t["price"]; ep = pos["ep"]
            g = ((p - ep) / ep * 100) if pos["side"] == "LONG" else ((ep - p) / ep * 100)
            pos["max_g"] = max(pos.get("max_g", 0), g)
            mg = pos["max_g"]; reason = ""
            if mg > 0.3 and g < mg - self.TRAIL_PCT: reason = f"TRAIL(g={g:.2f}%,max={mg:.2f}%)"
            elif g > 8.0: reason = f"BIG_TP({g:.2f}%)"
            elif g < -3.0: reason = f"STOP({g:.2f}%)"
            else:
                hrs = (datetime.now(timezone.utc) - datetime.fromisoformat(pos["ts"].replace("Z", "+00:00"))).total_seconds() / 3600
                if hrs > 48 and g < 0.3: reason = f"TIME({hrs:.0f}h,g={g:.2f}%)"
            if reason:
                try:
                    from utils import load_environment_from_gpg
                    env = load_environment_from_gpg()
                    import ccxt.async_support as ccxt
                    ex = ccxt.binance({"apiKey": env.get(f"BINANCE_API_KEY_{self.ACCOUNT.upper()}"), "secret": env.get(f"BINANCE_API_SECRET_{self.ACCOUNT.upper()}"), "options": {"defaultType": "future"}})
                    await ex.create_market_order(pos["sym"], "sell" if pos["side"] == "LONG" else "buy", pos["qty"], params={"reduceOnly": True})
                    logger.warning(f"[BREAKOUT_HUNTER] 🔴 EXIT {key} {reason}")
                    del self._state[" positions"][key]
                    await ex.close()
                except Exception as e:
                    logger.error(f"[BREAKOUT_HUNTER] ❌ EXIT {key}: {e}")

class AdvancedSignalRater:
    @staticmethod
    async def rate(account_key, symbol, is_long, current_price, metrics, ind, prev_cross_price, is_exit, is_allowed, avg_entry=0.0, last_exit_timestamp=None, last_reduction_price=0.0, scalping_mode=False, scalping_override=False, tracker_data=None, tracker_manager=None, skip_boycott=False, data_manager=None):
        scalp_accounts = getattr(config, 'SCALP_ACCOUNTS', [])
        if isinstance(scalp_accounts, tuple): scalp_accounts = list(scalp_accounts)
        should_scalp = scalping_mode and account_key in scalp_accounts
        score = 0.0; i=ind
        reasons = []
        now = datetime.now(timezone.utc)
        now_ts = time.time()
        cand = tracker_manager._exit_template()
        position_side='LONG' if is_long else 'SHORT'
        position_key = construct_position_key(account_key, symbol, position_side)
        _rpk = f"{symbol}_{position_side}"  # regime lookup key (without account prefix for get_symbol_setting)
        position = await tracker_manager.get_position(position_key)
        if not position: position = tracker_manager.positions_service.positions.get(position_key)
        if not position: position = tracker_manager.positions_service.positions_by_account.get(account_key, {}).get(position_key)
        positionAmt = 0.0
        gain = 0.0
        prev_gain = 0.0
        if position:
            gain = getattr(position, 'gain', 0.0)
            prev_gain = getattr(position, 'prev_gain', 0.0)
            positionAmt = getattr(position, 'positionAmt', 0.0)
            
        fetched_cand = tracker_data or await tracker_manager.get_exit_candidate(position_key)
        if not isinstance(fetched_cand, dict): fetched_cand = None
        cand = fetched_cand if fetched_cand is not None else tracker_manager._exit_template()
        is_hedge = cand.get('is_hedge', False)

        # ── GLOBAL STALENESS GATE ─────────────────────────────────────────────
        # Only block if 15m data itself is >90 min old (extreme staleness).
        # Stale 1m/3m data is handled in get_hot_state (neutralized to 50).
        # Exits always allowed. Big winners (>=3%) bypass to allow augmentation.
        _winner_bypass = gain >= 3.0 and positionAmt > 0
        if not is_exit and not is_hedge and not _winner_bypass:
            try:
                _bridge_ts = safe_fetch_float(metrics.get('_tick_ts', 0), 0)
                _bridge_fresh = (time.time() - _bridge_ts) < 120.0 if _bridge_ts > 0 else False
                _ts15m = ind.get('timestamp_15m') or ind.get('timestamp', '')
                if _ts15m and not _bridge_fresh:
                    _ts_dt = datetime.fromisoformat(str(_ts15m).replace('Z', '+00:00'))
                    _age_min = (datetime.now(timezone.utc) - _ts_dt).total_seconds() / 60.0
                    if _age_min > 90.0:
                        logger.error(f"[rate] {position_key}: ❌ BLOCKED - STALE_INDICATORS ({_age_min:.0f}m old, ts={str(_ts15m)[:19]})")
                        return 0, "WAIT", f"STALE_INDICATORS_{_age_min:.0f}m"
            except Exception: pass
        # ─────────────────────────────────────────────────────────────────────

        # BASIS_CONDITION BOYCOTT
        if getattr(config, 'BASIS_CONDITION', False) and not is_exit and not skip_boycott:
            b15 = safe_fetch_float(ind.get('dc_basis_15m'), 0)
            b1h = safe_fetch_float(ind.get('dc_basis_1h'), 0)
            b4h = safe_fetch_float(ind.get('dc_basis_4h'), 0)
            bd = safe_fetch_float(ind.get('dc_basis_D'), 0)
            k15 = safe_fetch_float(ind.get('stoch_k_15m'), 50)
            d15 = safe_fetch_float(ind.get('stoch_d_15m'), 50)
            s1h = safe_fetch_float(ind.get("sma_200_1h"), 0) #TEMP IN
            if b15 > 0 and b1h > 0 and b4h > 0 and bd > 0:
                if is_long:
                    if current_price < b15 or current_price < b1h:
                        return -100.0, "BOYCOTT", "BELOW_BASIS_ALL_TF"
                    if k15 < d15:
                        return -100.0, "BOYCOTT", "STOCH_15M_BEARISH"
                    if (s1h > 0 and current_price < s1h) :
                        return -100.0, "BOYCOTT", "BELOW_SMA200"
                else:
                    if current_price > b15 or current_price > b1h or current_price > b4h or current_price > bd:
                        return -100.0, "BOYCOTT", "ABOVE_BASIS_ALL_TF"
                    if k15 > d15:
                        return -100.0, "BOYCOTT", "STOCH_15M_BULLISH"
                    if (s1h > 0 and current_price > s1h) :
                        return -100.0, "BOYCOTT", "ABOVE_SMA200"

        # SCALP MOMENTUM BOYCOTT — uses WT micro TF direction (superior to stoch K direction)
        if should_scalp and not is_exit:
            _wt_bull_1m = metrics.get(f'wt_bullish_{getattr(config, "TF_MICRO", "1m")}', ind.get(f'wt_bullish_{getattr(config, "TF_MICRO", "1m")}'))
            if _wt_bull_1m is not None:
                if is_long and not _wt_bull_1m:
                    return -100.0, "BOYCOTT", "SCALP_WT1M_BEARISH"
                elif not is_long and _wt_bull_1m:
                    return -100.0, "BOYCOTT", "SCALP_WT1M_BULLISH"
            else:
                # Fallback to stoch K if WT not available
                k1 = safe_fetch_float(metrics.get('stoch_k_1m'), 50)
                k1p = safe_fetch_float(metrics.get('k_1m_prev'), 50)
                if is_long and k1 < k1p:
                    return -100.0, "BOYCOTT", "SCALP_1M_DIR_WRONG_LONG"
                elif not is_long and k1 > k1p:
                    return -100.0, "BOYCOTT", "SCALP_1M_DIR_WRONG_SHORT"
        # ═══════════════════════════════════════════════════════════════════
        # 2026-04-18 INDICATOR-AUDIT EXPERIMENTAL GATES (ALL DEFAULT OFF)
        # R-G1 / R-G2 / R-G3 — see config.py SENTIMENT_TOP_N_GATE_ENABLED,
        # WT_MTF_VEL_GATE_ENABLED, WT_CHOP_GATE_ENABLED. Entries only (skip on
        # is_exit). Fail-OPEN on missing data so broken sentiment feed does
        # not lock trading.
        # ═══════════════════════════════════════════════════════════════════
        if not is_exit and not is_hedge:
            # R-G1: cross-symbol sentiment rank boycott
            if getattr(config, 'SENTIMENT_TOP_N_GATE_ENABLED', False):
                _rank = int(safe_fetch_float(ind.get('0sentiment_rank'), 0) or 0)
                _rp = safe_fetch_float(ind.get('0ranking_points'), -1.0)
                _top_n = int(getattr(config, 'SENTIMENT_TOP_N', 20))
                if _rank > 0:
                    if is_long and _rank > _top_n:
                        return -100.0, "BOYCOTT", f"SENT_RANK_LONG_{_rank}>{_top_n}"
                    # SHORT: approximate bottom-N via ranking_points (0..100 linear from rank).
                    # For top_n=20 on ~350-universe: bottom-20 ≈ rp<=5.7. Threshold scales with top_n.
                    if (not is_long) and _rp >= 0:
                        _rp_thr = _top_n * 100.0 / 350.0
                        if _rp > _rp_thr:
                            return -100.0, "BOYCOTT", f"SENT_RANK_SHORT_RP={_rp:.0f}>{_rp_thr:.0f}"
            # R-G2: MTF WT velocity alignment gate
            if getattr(config, 'WT_MTF_VEL_GATE_ENABLED', False):
                _min_tf = int(getattr(config, 'WT_MTF_VEL_MIN', 3))
                _up_ct = int(safe_fetch_float(ind.get('wt_velocity_up_count'), -1) or -1)
                _dn_ct = int(safe_fetch_float(ind.get('wt_velocity_down_count'), -1) or -1)
                if is_long and 0 <= _up_ct < _min_tf:
                    return -100.0, "BOYCOTT", f"WT_MTF_VEL_LONG_{_up_ct}<{_min_tf}"
                if (not is_long) and 0 <= _dn_ct < _min_tf:
                    return -100.0, "BOYCOTT", f"WT_MTF_VEL_SHORT_{_dn_ct}<{_min_tf}"
            # R-G3: chop boycott via wt_cross_count on LTFs
            if getattr(config, 'WT_CHOP_GATE_ENABLED', False):
                _chop_max = int(getattr(config, 'WT_CHOP_MAX', 8))
                _chop_key = 'wt_cross_count_bull_' if is_long else 'wt_cross_count_bear_'
                _chop_tfs = 0
                for _tf in ('3m', '15m', '1h'):
                    _cnt = int(safe_fetch_float(ind.get(f'{_chop_key}{_tf}'), 0) or 0)
                    if _cnt >= _chop_max:
                        _chop_tfs += 1
                if _chop_tfs >= 2:
                    return -100.0, "BOYCOTT", f"WT_CHOP_{_chop_tfs}TF_dir={'L' if is_long else 'S'}"
            # R-G4: composite WT delta gate — blocks when ALL TFs trending against entry direction
            if getattr(config, 'WT_COMPOSITE_DELTA_GATE_ENABLED', True):
                _cd = safe_fetch_float(ind.get('wt_composite_delta'), None)
                if _cd is not None:
                    if is_long and _cd < getattr(config, 'WT_COMPOSITE_DELTA_LONG_MIN', -100.0):
                        return -100.0, "BOYCOTT", f"WT_CDELTA_LONG_{_cd:.0f}<{getattr(config,'WT_COMPOSITE_DELTA_LONG_MIN',-100.0):.0f}"
                    if (not is_long) and _cd > getattr(config, 'WT_COMPOSITE_DELTA_SHORT_MAX', 100.0):
                        return -100.0, "BOYCOTT", f"WT_CDELTA_SHORT_{_cd:.0f}>{getattr(config,'WT_COMPOSITE_DELTA_SHORT_MAX',100.0):.0f}"
            # R-G5: exhaust entry gate — blocks entering into an exhausted move (3m + 15m both exhausted in entry dir)
            if getattr(config, 'WT_EXHAUST_ENTRY_GATE_ENABLED', True):
                _ex_3m = str(ind.get('wt_momentum_state_3m', '') or '').upper()
                _ex_15m = str(ind.get('wt_momentum_state_15m', '') or '').upper()
                if is_long and _ex_3m == 'EXHAUST_UP' and _ex_15m == 'EXHAUST_UP':
                    return -100.0, "BOYCOTT", "WT_EXHAUST_LONG_3m+15m"
                if (not is_long) and _ex_3m == 'EXHAUST_DOWN' and _ex_15m == 'EXHAUST_DOWN':
                    return -100.0, "BOYCOTT", "WT_EXHAUST_SHORT_3m+15m"
            # R-G6: D-level percentile gate — blocks entries at daily extremes
            if getattr(config, 'WT_PERCENTILE_ENTRY_GATE_ENABLED', True):
                _pct_D_e = safe_fetch_float(ind.get('wt_percentile_D'), None)
                if _pct_D_e is not None:
                    if is_long and _pct_D_e > getattr(config, 'WT_PERCENTILE_ENTRY_OB_D', 90.0):
                        return -100.0, "BOYCOTT", f"WT_PCT_LONG_OB_D={_pct_D_e:.0f}"
                    if (not is_long) and _pct_D_e < getattr(config, 'WT_PERCENTILE_ENTRY_OS_D', 10.0):
                        return -100.0, "BOYCOTT", f"WT_PCT_SHORT_OS_D={_pct_D_e:.0f}"
            # R-G7: divergence entry gate — wt_any_bear_div blocks LONG; wt_any_bull_div blocks SHORT
            if getattr(config, 'WT_DIV_ENTRY_GATE_ENABLED', True):
                if is_long and bool(ind.get('wt_any_bear_div', False)):
                    return -100.0, "BOYCOTT", "WT_BEAR_DIV_BLOCKS_LONG"
                if (not is_long) and bool(ind.get('wt_any_bull_div', False)):
                    return -100.0, "BOYCOTT", "WT_BULL_DIV_BLOCKS_SHORT"
            # R-G10: HTF-only divergence hard gate. Bear div on 4h or D blocks LONG; mirror for SHORT.
            # Stricter than R-G7 which checks wt_any_bear_div (any TF). R-G10 explicitly targets cycle tops/bottoms.
            if bool(getattr(config, 'R_G10_HTF_DIV_GATE_ENABLED', False)):
                _htf_tfs_str = str(getattr(config, 'R_G10_HTF_DIV_TFS', '4h,D') or '')
                _htf_tfs = [t.strip() for t in _htf_tfs_str.split(',') if t.strip()]
                _htf_against = None
                for _htf in _htf_tfs:
                    _hd = str(ind.get(f'wt_divergence_{_htf}', '') or '').upper()
                    if is_long and _hd == 'BEAR':
                        _htf_against = f"BEAR_{_htf}"
                        break
                    elif (not is_long) and _hd == 'BULL':
                        _htf_against = f"BULL_{_htf}"
                        break
                if _htf_against:
                    return -100.0, "BOYCOTT", f"R_G10_HTF_DIV_{_htf_against}"
            # R-G8 / R-S6: multi-TF wt_momentum_state gate.
            # mode 0=OFF, 1=block_any_LTF_EXHAUST (3m/15m), 2=block_any_TF_EXHAUST (all 5), 3=warn_only.
            _mstate_mode = int(getattr(config, 'R_S6_WT_MSTATE_GATE_MODE', 0))
            if _mstate_mode > 0:
                _mstate_tfs = ('3m', '15m') if _mstate_mode == 1 else (('3m', '15m', '1h', '4h', 'D') if _mstate_mode in (2, 3) else ())
                _exhaust_target = 'EXHAUST_UP' if is_long else 'EXHAUST_DOWN'
                _hits = []
                for _tf in _mstate_tfs:
                    _st = str(ind.get(f'wt_momentum_state_{_tf}', '') or '').upper()
                    if _st == _exhaust_target:
                        _hits.append(_tf)
                if _hits:
                    if _mstate_mode == 3:
                        # warn-only — do not block
                        try:
                            logger.info(f"[R_S6_MSTATE_WARN] {position_key}: {_hits} in {_exhaust_target} — would block (mode=3)")
                        except Exception:
                            pass
                    else:
                        return -100.0, "BOYCOTT", f"R_S6_MSTATE_{'-'.join(_hits)}_{_exhaust_target}"
        if not is_hedge:
            if cand.get('is_hedge') is True: is_hedge = True
            elif "HEDGE" in str(cand.get('last_reason', '')).upper(): is_hedge = True
            elif any("HEDGE" in str(log.get('reason', '')).upper() for log in cand.get('trade_log', [])[-5:]): is_hedge = True
            elif any(h.get('position_key') == position_key for h in tracker_manager.active_hedges): is_hedge = True
        _is_hedged_by_other = cand.get('is_hedged', False) or any(h.get('losing_position_key') == position_key for h in tracker_manager.active_hedges)
        _hedge_coverage_usd = safe_fetch_float(cand.get('hedged_for_total_$', 0), 0.0)
        _tk = tracker_manager.tradeable_keys or tracker_manager.tradeable_keys_cache or set(); is_tradeable = (not _tk) or position_key in _tk or position_key in tracker_manager.tradeable_position_keys.get(account_key, set())
        # TEMP KEY CHECK: red zone counter-trend trades get temporary tradeable_key status
        _is_temp_key = False
        if not is_tradeable and hasattr(data_manager, 'delta_tracker') and data_manager.delta_tracker:
            _temp_active = data_manager.delta_tracker.temp_keys.get_active_keys(account_key)
            if position_key in _temp_active:
                is_tradeable = True
                _is_temp_key = True
        if not is_tradeable and (not position or positionAmt <= 0): return 0, "NOT A TRADEABLE KEY", f'{position_key} NOT TRADEABLE'
        if not last_reduction_price: last_reduction_price = position.last_reduction_price if position else current_price
        if not is_allowed and not is_exit: return 0, "WAIT", "Not Allowed"
