            if pos_last_aug and minutes_since(pos_last_aug) < 24 and gain < config.MIN_GAIN: 
                return 0, 'NO_GAIN_WAIT_HAS BEEN AUGMENTED ALREADY', 'NO_GAIN_WAIT_NO DOUBLE AUG'
            knife_penalty = 0.0      
