                        _loser_wt1_3m = safe_fetch_float(_loser_ind.get('wt1_3m', 0), 0.0)
                        _loser_wt2_3m = safe_fetch_float(_loser_ind.get('wt2_3m', 0), 0.0)
                        _hwtk_tf = str(getattr(self.config, 'HEDGE_WT_KILL_CONFIRM_TF', '1h'))
