def detect_volume_spike(symbol: str, is_long: bool, indicators: dict, metrics: dict) -> str:
    """Detect volume spike reversal: high-volume strong-body candle on 15m = fade the move. Returns None, 'BUY' (fade bearish spike), or 'SELL' (fade bullish spike)."""
    if not getattr(config, "VOL_SPIKE_ENABLED", False):
        return None
    relvol = safe_fetch_float(indicators.get('relative_volume_15m', 0), 0)
    relvol_thresh = getattr(config, "VOL_SPIKE_RELVOL_THRESHOLD", 3.0)
    if relvol < relvol_thresh:
        return None
    high_15m = safe_fetch_float(indicators.get('high_15m', 0), 0)
    low_15m = safe_fetch_float(indicators.get('low_15m', 0), 0)
    open_15m = safe_fetch_float(indicators.get('open_15m', 0), 0)
    close_15m = safe_fetch_float(indicators.get('close_15m', 0), 0)
    candle_range = high_15m - low_15m
    if candle_range <= 0 or high_15m <= 0 or open_15m <= 0 or close_15m <= 0:
        return None
    body = abs(close_15m - open_15m)
    body_ratio = body / candle_range
    body_thresh = getattr(config, "VOL_SPIKE_BODY_RATIO", 0.7)
    if body_ratio < body_thresh:
        return None
    is_bearish_candle = close_15m < open_15m
    if is_bearish_candle and is_long:
        return 'BUY'
    elif not is_bearish_candle and not is_long:
        return 'SELL'
    return None

def detect_bb_squeeze_breakout(symbol: str, is_long: bool, indicators: dict) -> str:
    """Detect BB squeeze breakout: width compresses below 20th percentile then price breaks out. Returns None, 'BUY', or 'SELL'."""
    if not getattr(config, "BB_SQUEEZE_ENABLED", False):
        return None
    bb_upper = safe_fetch_float(indicators.get('bb_upper_1h', 0), 0)
    bb_lower = safe_fetch_float(indicators.get('bb_lower_1h', 0), 0)
    bb_pct_b = safe_fetch_float(indicators.get('bb_pct_b_1h', 0.5), 0.5)
    if bb_lower <= 0 or bb_upper <= 0:
        return None
    bb_width = (bb_upper - bb_lower) / bb_lower * 100.0
    if symbol not in _bb_squeeze_state:
        _bb_squeeze_state[symbol] = {'in_squeeze': False, 'squeeze_bars': 0, 'width_at_squeeze': 0.0, 'width_history': deque(maxlen=100)}
    state = _bb_squeeze_state[symbol]
    state['width_history'].append(bb_width)
    if len(state['width_history']) < 20:
        return None
    width_percentile = getattr(config, "BB_SQUEEZE_WIDTH_PERCENTILE", 0.2)
    sorted_widths = sorted(state['width_history'])
    threshold_idx = max(0, int(len(sorted_widths) * width_percentile) - 1)
    squeeze_threshold = sorted_widths[threshold_idx]
    if not state['in_squeeze']:
        if bb_width <= squeeze_threshold:
            state['in_squeeze'] = True
            state['squeeze_bars'] = 1
            state['width_at_squeeze'] = bb_width
        return None
    state['squeeze_bars'] += 1
    if bb_width > squeeze_threshold * 1.5:
        if bb_pct_b > 1.0 and is_long:
            state['in_squeeze'] = False
            state['squeeze_bars'] = 0
            return 'BUY'
        elif bb_pct_b < 0.0 and not is_long:
            state['in_squeeze'] = False
            state['squeeze_bars'] = 0
            return 'SELL'
        state['in_squeeze'] = False
        state['squeeze_bars'] = 0
    if state['squeeze_bars'] > 800:
        state['in_squeeze'] = False
        state['squeeze_bars'] = 0
    return None

def _get_bb_pctb(symbol: str, tf: str, indicators: dict) -> float:
    """Get bb_pct_b for a given TF. If not in indicators (backtest NPZ), compute from rolling close prices."""
    pctb = safe_fetch_float(indicators.get(f'bb_pct_b_{tf}'), None)
    if pctb is not None:
        return pctb
    # Fallback: compute from close price + rolling 20-bar SMA/stdev
    close = safe_fetch_float(indicators.get(f'close_{tf}', 0), 0)
    if close <= 0:
        close = safe_fetch_float(indicators.get('current_price', 0), 0)
    if close <= 0:
        return 0.5
    buf_key = f"{symbol}_{tf}"
    if buf_key not in _stdev_bb_history:
        _stdev_bb_history[buf_key] = deque(maxlen=20)
    buf = _stdev_bb_history[buf_key]
    # Only append if close changed (HTF values are forward-filled in backtest)
    if not buf or abs(buf[-1] - close) > 1e-8:
        buf.append(close)
    if len(buf) < 20:
        return 0.5
    vals = list(buf)
    mean = sum(vals) / len(vals)
    variance = sum((v - mean) ** 2 for v in vals) / len(vals)
    std = variance ** 0.5
    if std <= 0:
        return 0.5
    upper = mean + 2.0 * std
    lower = mean - 2.0 * std
    band_width = upper - lower
    if band_width <= 0:
        return 0.5
    return (close - lower) / band_width


def detect_stdev_breakout(symbol: str, is_long: bool, indicators: dict, metrics: dict) -> Optional[dict]:
    """Detect 2.5σ HTF breakout + LTF retest scaling. Returns None or dict with signal/phase/score/size_mult."""
    if not getattr(config, "STDEV_BREAKOUT_ENABLED", False):
        return None
    htf_list = getattr(config, "STDEV_BREAKOUT_HTF_LIST", ["D", "4h"])
    retest_tf_list = getattr(config, "STDEV_BREAKOUT_RETEST_TF_LIST", ["1h", "15m"])
    pctb_long = getattr(config, "STDEV_BREAKOUT_PCTB_LONG", 1.125)
    pctb_short = getattr(config, "STDEV_BREAKOUT_PCTB_SHORT", -0.125)
    rvol_min = getattr(config, "STDEV_BREAKOUT_RVOL_MIN", 1.2)
    max_retests = getattr(config, "STDEV_BREAKOUT_MAX_RETESTS", 3)
    max_age = getattr(config, "STDEV_BREAKOUT_MAX_AGE_BARS", 50)
    retest_pctb_min = getattr(config, "STDEV_BREAKOUT_RETEST_PCTB_MIN", 0.85)
    retest_pctb_max = getattr(config, "STDEV_BREAKOUT_RETEST_PCTB_MAX", 1.05)
    if symbol not in _stdev_breakout_state:
        _stdev_breakout_state[symbol] = {'active': False, 'direction': None, 'breakout_time': 0.0, 'breakout_pctb': 0.0, 'htf': None, 'retest_count': 0, 'bars_since': 0}
    state = _stdev_breakout_state[symbol]
    # Phase 1: Check for NEW HTF breakout
    if not state['active']:
        for tf in htf_list:
            pctb = _get_bb_pctb(symbol, tf, indicators)
            rvol = safe_fetch_float(indicators.get(f'relative_volume_{tf}', 0), 0)
            # Fallback: use rvol from lower TF if HTF rvol not available
            if rvol <= 0:
                rvol = safe_fetch_float(indicators.get('relative_volume_1h', 0), 0)
            if rvol <= 0:
                rvol = safe_fetch_float(indicators.get('relative_volume_15m', 0), 0)
            if is_long and pctb > pctb_long and rvol >= rvol_min:
                state['active'] = True
                state['direction'] = 'LONG'
                state['breakout_time'] = time.time()
                state['breakout_pctb'] = pctb
                state['htf'] = tf
                state['retest_count'] = 0
                state['bars_since'] = 0
                return {'signal': 'BUY', 'phase': 'BREAKOUT', 'htf': tf, 'pctb': pctb, 'rvol': rvol, 'size_mult': 1.0, 'score': getattr(config, "STDEV_BREAKOUT_SCORE", 25)}
            elif not is_long and pctb < pctb_short and rvol >= rvol_min:
                state['active'] = True
                state['direction'] = 'SHORT'
                state['breakout_time'] = time.time()
                state['breakout_pctb'] = pctb
                state['htf'] = tf
                state['retest_count'] = 0
                state['bars_since'] = 0
                return {'signal': 'SELL', 'phase': 'BREAKOUT', 'htf': tf, 'pctb': pctb, 'rvol': rvol, 'size_mult': 1.0, 'score': getattr(config, "STDEV_BREAKOUT_SCORE", 25)}
        return None
    # Expire stale breakouts
    state['bars_since'] += 1
    if state['bars_since'] > max_age:
        state['active'] = False
        return None
    # Check direction mismatch (we track LONG breakout but checking SHORT slot, or vice versa)
    if (is_long and state['direction'] != 'LONG') or (not is_long and state['direction'] != 'SHORT'):
        return None
    # Phase 2: Check for LTF retest entry
    if state['retest_count'] >= max_retests:
        return None
    for tf in retest_tf_list:
        pctb = _get_bb_pctb(symbol, tf, indicators)
        k_tf = safe_fetch_float(indicators.get(f'stoch_k_{tf}', 50), 50)
        d_tf = safe_fetch_float(indicators.get(f'stoch_d_{tf}', 50), 50)
        if is_long:
            # LONG retest: pctb pulled back near upper band + stoch bouncing up
            retest_pullback = retest_pctb_min <= pctb <= retest_pctb_max
            stoch_bounce = k_tf > d_tf and k_tf < 65
            if retest_pullback and stoch_bounce:
                state['retest_count'] += 1
                size_mult = getattr(config, "STDEV_BREAKOUT_RETEST_SIZE_MULT", 1.5)
                return {'signal': 'BUY', 'phase': 'RETEST', 'htf': state['htf'], 'retest_tf': tf, 'pctb': pctb, 'retest_num': state['retest_count'], 'size_mult': size_mult, 'score': getattr(config, "STDEV_BREAKOUT_RETEST_SCORE", 22)}
        else:
            # SHORT retest: pctb bounced back near lower band + stoch falling
            retest_pullback = (1.0 - retest_pctb_max) <= pctb <= (1.0 - retest_pctb_min)
            stoch_bounce = k_tf < d_tf and k_tf > 35
            if retest_pullback and stoch_bounce:
                state['retest_count'] += 1
                size_mult = getattr(config, "STDEV_BREAKOUT_RETEST_SIZE_MULT", 1.5)
                return {'signal': 'SELL', 'phase': 'RETEST', 'htf': state['htf'], 'retest_tf': tf, 'pctb': pctb, 'retest_num': state['retest_count'], 'size_mult': size_mult, 'score': getattr(config, "STDEV_BREAKOUT_RETEST_SCORE", 22)}
    return None


def check_stdev_breakout_exit(symbol: str, is_long: bool, indicators: dict) -> Optional[str]:
    """Check if a STDEV_BREAKOUT position should exit (breakout failed). Returns reason string or None."""
    if not getattr(config, "STDEV_BREAKOUT_ENABLED", False):
        return None
    if symbol not in _stdev_breakout_state:
        return None
    state = _stdev_breakout_state[symbol]
    if not state['active']:
        return None
    exit_pctb_fail = getattr(config, "STDEV_BREAKOUT_EXIT_PCTB_FAIL", 0.75)
    htf = state.get('htf', 'D')
    pctb = _get_bb_pctb(symbol, htf, indicators)
    # Breakout failed: price retreated back inside bands
    if is_long and pctb < exit_pctb_fail:
        state['active'] = False
        return f"STDEV_BREAKOUT_FAILED_{htf}_pctb={pctb:.3f}<{exit_pctb_fail}"
    elif not is_long and pctb > (1.0 - exit_pctb_fail):
        state['active'] = False
        return f"STDEV_BREAKOUT_FAILED_{htf}_pctb={pctb:.3f}>{1.0-exit_pctb_fail:.3f}"
    # WT turn against on 1h
    if getattr(config, "STDEV_BREAKOUT_EXIT_WT_ENABLED", True):
        wt1_1h = safe_fetch_float(indicators.get('wt1_1h', 0), 0)
        wt2_1h = safe_fetch_float(indicators.get('wt2_1h', 0), 0)
        if is_long and wt1_1h < wt2_1h and wt1_1h > 60:
            state['active'] = False
            return f"STDEV_BREAKOUT_WT_EXIT_1h_wt1={wt1_1h:.1f}<wt2={wt2_1h:.1f}"
        elif not is_long and wt1_1h > wt2_1h and wt1_1h < -60:
            state['active'] = False
            return f"STDEV_BREAKOUT_WT_EXIT_1h_wt1={wt1_1h:.1f}>wt2={wt2_1h:.1f}"
    return None


async def get_ls_ratio(tracker_manager, account_key: str) -> tuple:
    """Returns (ratio, long_val, short_val) for account. ratio=long/short.
    Prefers live positions_service (fresh positionAmt/mark_price). Falls back to exit_candidates
    when positions_service is unavailable or empty."""
    long_val = 0.0
    short_val = 0.0
    _svc = getattr(tracker_manager, 'positions_service', None)
    _live_positions = None
    if _svc is not None:
        _live_positions = getattr(_svc, 'positions_by_account', {}).get(account_key, {}) or None
    if _live_positions:
        for _pk, _pos in _live_positions.items():
            _amt = abs(safe_fetch_float(getattr(_pos, 'positionAmt', 0), 0))
            if _amt < 0.0001: continue
            _price = safe_fetch_float(getattr(_pos, 'mark_price', 0) or getattr(_pos, 'entry_price', 0), 0)
            _val = _amt * _price
            if _pk.endswith("_LONG"):
                long_val += _val
            elif _pk.endswith("_SHORT"):
                short_val += _val
    else:
        async with tracker_manager._exit_candidates_lock:
            for k, v in tracker_manager.exit_candidates.items():
                if v.get("status") != "active": continue
                ak, sym, ps = parse_position_key(k)
                if ak != account_key: continue
                amt = safe_fetch_float(v.get("positionAmt", 0))
                price = safe_fetch_float(v.get("mark_price", 0))
                val = abs(amt * price)
                if ps == "LONG" and amt > 0:
                    long_val += val
                elif ps == "SHORT" and amt > 0:
                    short_val += val
    ratio = long_val / short_val if short_val > 0 else (999.0 if long_val > 0 else 1.0)
    return ratio, long_val, short_val


def compute_side_pnl(tracker_manager, account_key: str) -> tuple:
    """Returns (long_avg_gain_pct, short_avg_gain_pct, long_count, short_count, pnl_delta).
    pnl_delta = long_avg - short_avg (positive means longs winning). Uses live positions_service."""
    _lg = 0.0; _lc = 0
    _sg = 0.0; _sc = 0
    _svc = getattr(tracker_manager, 'positions_service', None)
    if _svc is None:
        return 0.0, 0.0, 0, 0, 0.0
    _positions = getattr(_svc, 'positions_by_account', {}).get(account_key, {}) or {}
    for _pk, _pos in _positions.items():
        _amt = abs(safe_fetch_float(getattr(_pos, 'positionAmt', 0), 0))
        if _amt < 0.0001: continue
        _gain = safe_fetch_float(getattr(_pos, 'gain', 0), 0)
        if _pk.endswith("_LONG"):
            _lg += _gain; _lc += 1
        elif _pk.endswith("_SHORT"):
            _sg += _gain; _sc += 1
    _long_avg = (_lg / _lc) if _lc else 0.0
    _short_avg = (_sg / _sc) if _sc else 0.0
    return _long_avg, _short_avg, _lc, _sc, (_long_avg - _short_avg)


def check_htf_direction_gate(indicators: dict, is_long: bool, current_price: float) -> tuple:
    """Returns (passes, signals_met, total_signals, reason_str).
    Counts how many of the four HTF signals (wt_D, wt_4h, wt_1h, price_vs_sma200_D) align with trade direction.
    Respects HTF_GATE_D_MANDATORY and HTF_GATE_MIN_CONFIRMATIONS from config."""
    if not isinstance(indicators, dict):
        return False, 0, 4, "HTF_GATE_NO_INDICATORS"
    _wt1_d = safe_fetch_float(indicators.get('wt1_D'), 0)
    _wt2_d = safe_fetch_float(indicators.get('wt2_D'), 0)
    _wt1_4h = safe_fetch_float(indicators.get('wt1_4h'), 0)
    _wt2_4h = safe_fetch_float(indicators.get('wt2_4h'), 0)
    _wt1_1h = safe_fetch_float(indicators.get('wt1_1h'), 0)
    _wt2_1h = safe_fetch_float(indicators.get('wt2_1h'), 0)
    _sma_d = safe_fetch_float(indicators.get('sma_200_D'), 0)
    _include_sma = bool(getattr(config, 'HTF_GATE_SIGNALS_SMA200D', True))
    if is_long:
        _d_ok = (_wt1_d > _wt2_d) and _wt1_d != 0 and _wt2_d != 0
        _4h_ok = (_wt1_4h > _wt2_4h) and _wt1_4h != 0 and _wt2_4h != 0
        _1h_ok = (_wt1_1h > _wt2_1h) and _wt1_1h != 0 and _wt2_1h != 0
        _sma_ok = (current_price > _sma_d) if (_include_sma and _sma_d > 0) else None
    else:
        _d_ok = (_wt1_d < _wt2_d) and _wt1_d != 0 and _wt2_d != 0
        _4h_ok = (_wt1_4h < _wt2_4h) and _wt1_4h != 0 and _wt2_4h != 0
        _1h_ok = (_wt1_1h < _wt2_1h) and _wt1_1h != 0 and _wt2_1h != 0
        _sma_ok = (current_price < _sma_d) if (_include_sma and _sma_d > 0) else None
    _signals = [_d_ok, _4h_ok, _1h_ok]
    _total = 3
    if _sma_ok is not None:
        _signals.append(_sma_ok)
        _total = 4
    _met = sum(1 for s in _signals if s)
    _min_conf = int(getattr(config, 'HTF_GATE_MIN_CONFIRMATIONS', 3))
    _d_required = bool(getattr(config, 'HTF_GATE_D_MANDATORY', True))
    _reason = f"HTF[D={'✓' if _d_ok else '✗'}({_wt1_d:.0f}/{_wt2_d:.0f}) 4h={'✓' if _4h_ok else '✗'}({_wt1_4h:.0f}/{_wt2_4h:.0f}) 1h={'✓' if _1h_ok else '✗'}({_wt1_1h:.0f}/{_wt2_1h:.0f})"
    if _sma_ok is not None:
        _reason += f" SMA={'✓' if _sma_ok else '✗'}(px={current_price:.4f} sma={_sma_d:.4f})"
    _reason += f" met={_met}/{_total} need={_min_conf} dReq={_d_required}]"
    if _d_required and not _d_ok:
        return False, _met, _total, f"HTF_D_FAIL_{_reason}"
    if _met < _min_conf:
        return False, _met, _total, f"HTF_CONF_FAIL_{_reason}"
    return True, _met, _total, f"HTF_PASS_{_reason}"


_realloc_cooldowns = {}


async def reallocate_capital_for_winner(trade_manager, tracker_manager, hedge_engine, account_key: str, winner_key: str, winner_gain: float, data_manager=None):
    """Close smallest profitable position to free capital for a big winner. Returns (freed_usd, donor_key) or (0, None)."""
    global _realloc_cooldowns
    _cd_key = f"realloc_{account_key}"
    if time.time() - _realloc_cooldowns.get(_cd_key, 0) < 300:
        return 0.0, None
    if winner_gain < 5.0:
        return 0.0, None
    acc_positions = tracker_manager.positions_service.positions_by_account.get(account_key, {})
    if not acc_positions:
        return 0.0, None
    hedged_keys = set()
    if hasattr(tracker_manager, 'active_hedges'):
        async with tracker_manager._hedges_lock:
            for h in tracker_manager.active_hedges:
                hedged_keys.add(h.get('position_key', ''))
                hedged_keys.add(h.get('losing_position_key', ''))
    candidates = []
    for pk, pos in acc_positions.items():
        if pk == winner_key:
            continue
        if pk in hedged_keys:
            continue
        p_amt = abs(safe_fetch_float(getattr(pos, 'positionAmt', 0.0), 0.0))
        if p_amt <= 0:
            continue
        p_gain = safe_fetch_float(getattr(pos, 'gain', 0.0), 0.0)
        p_price = safe_fetch_float(getattr(pos, 'mark_price', 0.0), 0.0)
        p_val = p_amt * p_price
        if p_gain < 0.10 or p_gain > 3.0:
            continue
        if p_val < 5.0:
            continue
        candidates.append((pk, pos, p_gain, p_val))
    if not candidates:
        logger.info(f"[CAPITAL_REALLOC] {account_key}: No eligible donor for {winner_key} (gain={winner_gain:.1f}%)")
        return 0.0, None
    candidates.sort(key=lambda x: x[2])
    donor_pk, donor_pos, donor_gain, donor_val = candidates[0]
    donor_amt = abs(safe_fetch_float(getattr(donor_pos, 'positionAmt', 0.0), 0.0))
    is_donor_long = donor_pk.endswith('_LONG')
    donor_side = 'SELL' if is_donor_long else 'BUY'
    donor_sym = parse_position_key(donor_pk)[1]
    donor_price = safe_fetch_float(getattr(donor_pos, 'mark_price', 0.0), 0.0)
    winner_sym = winner_key.split(':')[1].replace('_LONG', '').replace('_SHORT', '')
    logger.warning(f"\U0001f4b0 [CAPITAL_REALLOC] {account_key}: Closing {donor_pk} (gain={donor_gain:.2f}% val=${donor_val:.1f}) to fund {winner_key} (gain={winner_gain:.1f}%)")
    success, msg = await execute_trade_wrapper(trade_manager, tracker_manager, hedge_engine, account_key, donor_pk, donor_pos.positionAmt, 'CLOSE', donor_price, donor_amt, f"REALLOC_FOR_{winner_sym}_{winner_gain:.0f}pct", data_manager=data_manager)
    if success:
        _realloc_cooldowns[_cd_key] = time.time()
        logger.warning(f"\u2705 [CAPITAL_REALLOC] Freed ~${donor_val:.1f} from {donor_pk} for {winner_key}")
        return donor_val, donor_pk
    else:
        logger.error(f"\u274c [CAPITAL_REALLOC] Failed to close {donor_pk}: {msg}")
        _realloc_cooldowns[_cd_key] = time.time()
        return 0.0, None


async def execute_trade_wrapper(trade_manager, tracker_manager: TrackerManager, hedge_engine: HedgeEngine, account_key: str, position_key: str, positionAmt:float, action: str, current_price: float, qty: float, reason: str, already_locked: bool = False, is_hedge: bool = False, hedge_for: Optional[str] = None, override_qty: Optional[float] = None, verify_via_websocket: bool = True, data_manager: Optional[FastDataManager] = None) -> tuple[bool, str]:
    if hasattr(trade_manager, '_allowed_accounts') and account_key not in trade_manager._allowed_accounts:
        logger.critical(f"🛑 [EXECUTE_BLOCKED] Attempted trade for {account_key} but instance is restricted to {trade_manager._allowed_accounts}")
        return False, "ACCOUNT_MISMATCH"
    if account_key not in trade_manager.accounts:
        return False, f"IGNORED: Account {account_key} not loaded in TradeManager."
    # ═══════════════════════════════════════════════════════════════════════════
    # IRON GATE: Symbol MUST exist in symbols.json. NO EXCEPTIONS. NO BYPASS.
    # If it's not in the master symbol list, it does NOT exist. Period.
    # Added 2026-03-28 after TAUSDT hedge loss — symbol was never in symbols.json.
    # ═══════════════════════════════════════════════════════════════════════════
    _pk_parsed = parse_position_key(position_key)
    _gate_sym = _pk_parsed[1] if _pk_parsed else ""
    _master_symbols = getattr(trade_manager, 'symbols', set())
    if _gate_sym and _master_symbols and _gate_sym not in _master_symbols:
        logger.critical(f"🚫🚫🚫 [SYMBOL_NOT_IN_MASTER] {position_key}: symbol {_gate_sym} is NOT in symbols.json. TRADE BLOCKED. This symbol does not exist in our universe.")
        return False, f"BLOCKED_SYMBOL_NOT_IN_SYMBOLS_JSON_{_gate_sym}"
    # USDC PREFERENCE — redirect happens at execute_now level (before any lock).
    # By this point, USDT has already been upgraded to USDC when available.
    # This gate is kept only as a secondary anomaly detector (should never fire in normal flow).
    _action_u = (action or '').upper()
    _is_open_like = ('OPEN' in _action_u or 'AUGMENT' in _action_u or 'ENTRY' in _action_u or 'REENTRY' in _action_u) and not is_hedge
    if _is_open_like and _gate_sym and _gate_sym.endswith('USDT'):
        _usdc_candidate = _gate_sym[:-4] + 'USDC'
        _live_usdc = getattr(trade_manager, 'live_usdc_pairs', None) or getattr(trade_manager, 'available_usdc_pairs', set()) or set()
        if _usdc_candidate in _live_usdc:
            logger.warning(f"[USDC_GATE_ANOMALY] {position_key}: USDT reached gate despite upgrade — {_usdc_candidate} available. Proceeding on USDT.")
    # ═══════════════════════════════════════════════════════════════════════════
    # TRADEABLE_KEYS GATE — position MUST be in tradeable_keys.json. NO BYPASS.
    # Same-symbol hedges are exempt (the losing position IS tradeable).
    # Added 2026-04-08: 40-49% of opens were on non-tradeable symbols via hedge
    # paths that bypassed tradeable_keys. This gate catches ALL entry paths.
    # ═══════════════════════════════════════════════════════════════════════════
    _is_open_or_aug = action in ('OPEN', 'AUGMENT', 'REENTRY', 'REVERSE', 'REVERSE_AUGMENT', 'QUICK_OPEN', 'QUICK_AUGMENT', 'QUICK_HEDGE_OPEN', 'QUICK_HEDGE_AUGMENT', 'HEDGE_OPEN', 'DC_BREAKOUT', 'BB_SQUEEZE_BREAKOUT', 'VOL_SPIKE') or 'OPEN' in (action or '') or 'AUGMENT' in (action or '') or 'REENTRY' in (action or '') or 'ENTRY' in (action or '')
    _is_close_action = 'CLOSE' in (action or '').upper() or 'REDUCE' in (action or '').upper() or 'KILL' in (action or '').upper()
    if _is_open_or_aug and not _is_close_action:
        _tk = getattr(tracker_manager, 'tradeable_keys', None) or set()
        if _tk and position_key not in _tk:
            _is_same_sym_hedge = is_hedge and hedge_for
            _exempt = False
            if _is_same_sym_hedge:
                _hedge_sym_parsed = parse_position_key(hedge_for)
                _hedge_origin_sym = _hedge_sym_parsed[1] if _hedge_sym_parsed else ""
                if _hedge_origin_sym == _gate_sym:
                    _exempt = True
                else:
                    # 2026-04-17: USDT/USDC sibling hedge exemption. Origin USDT→hedge USDC (or vice
                    # versa) on same base asset is treated as same-symbol hedge (locked 1:1 price).
                    _origin_base = _hedge_origin_sym[:-4] if _hedge_origin_sym.endswith(('USDT','USDC')) else _hedge_origin_sym
                    _gate_base = _gate_sym[:-4] if _gate_sym.endswith(('USDT','USDC')) else _gate_sym
                    if _origin_base and _origin_base == _gate_base:
                        _exempt = True
                        logger.warning(f"⚠️ [TRADEABLE_KEYS_GATE_USDC_SIBLING_EXEMPT] {position_key}: hedge for {hedge_for} via sibling {_gate_sym} — allowing")
                        # Temporarily add to tradeable_keys so subsequent gates + tracker see it
                        if hasattr(tracker_manager, 'tradeable_keys') and isinstance(tracker_manager.tradeable_keys, set):
                            tracker_manager.tradeable_keys.add(position_key)
            if not _exempt:
                logger.critical(f"🚫 [TRADEABLE_KEYS_GATE] {position_key}: NOT in tradeable_keys ({len(_tk)} keys). BLOCKED. action={action} reason={reason[:60]}")
                return False, f"BLOCKED_NOT_TRADEABLE_{position_key}"
    # ═══════════════════════════════════════════════════════════════════════════
    # ABSOLUTE HEDGE SIZE CAP — NEVER allow a hedge larger than 200% of the
    # position it's protecting. This prevents 10x-20x hedge monsters that
    # eat the entire account. NO EXCEPTIONS. NO BYPASS.
    # ═══════════════════════════════════════════════════════════════════════════
    if is_hedge and hedge_for and current_price > 0:
        _origin_pos = await tracker_manager.get_position(hedge_for)
        if not _origin_pos:
            _origin_pos = tracker_manager.positions_service.positions_by_account.get(account_key, {}).get(hedge_for) if hasattr(tracker_manager, 'positions_service') else None
        _origin_val = abs(safe_fetch_float(getattr(_origin_pos, 'positionAmt', 0), 0)) * current_price if _origin_pos else 0
        _hedge_val = qty * current_price
        if _origin_val > 0 and _hedge_val > _origin_val * 2.0:
            _capped_qty = (_origin_val * 2.0) / current_price
            logger.critical(f"🚫🚫 [HEDGE_SIZE_CAP] {position_key}: hedge ${_hedge_val:.1f} > 200% of origin ${_origin_val:.1f}. CAPPING qty {qty:.6f} → {_capped_qty:.6f} (${_origin_val*2:.1f})")
            qty = _capped_qty
            if override_qty:
                override_qty = _capped_qty
        # Also block hedge if origin position is tiny (< MIN_POSITION_SIZE)
        if _origin_val > 0 and _origin_val < config.MIN_POSITION_SIZE:
            logger.warning(f"🚫 [HEDGE_TOO_SMALL] {position_key}: origin ${_origin_val:.1f} < MIN ${config.MIN_POSITION_SIZE}. Not worth hedging.")
            return False, f"BLOCKED_HEDGE_ORIGIN_TOO_SMALL_{_origin_val:.1f}"
        # Block if we can't find the origin (orphaned hedge)
        if not _origin_pos or abs(safe_fetch_float(getattr(_origin_pos, 'positionAmt', 0), 0)) < 0.0001:
            logger.warning(f"🚫 [HEDGE_ORPHAN] {position_key}: origin {hedge_for} has no position. Blocking orphan hedge.")
            return False, "BLOCKED_HEDGE_ORPHAN_NO_ORIGIN"
    # NOTE: No total hedge exposure cap — hedges must be free to protect the portfolio during market drops.
    # The 200% per-hedge cap above is sufficient to prevent runaway hedge monsters.
    _is_aug_action = action in ('OPEN', 'AUGMENT', 'REENTRY', 'REVERSE', 'REVERSE_AUGMENT', 'QUICK_OPEN', 'QUICK_AUGMENT', 'QUICK_HEDGE_OPEN', 'DC_BREAKOUT', 'BB_SQUEEZE_BREAKOUT', 'VOL_SPIKE') or 'OPEN' in action or 'AUGMENT' in action
    # ═══ ABSOLUTE HEDGE WT3M GATE — NO BYPASS, NO EXCEPTIONS ═══
    # LONG hedge CANNOT open/augment when wt1_3m <= wt2_3m.
    # SHORT hedge CANNOT open/augment when wt1_3m >= wt2_3m.
    # If WT3m is against the hedge, it will be killed within 5s by HEDGE_WT_KILL anyway.
    # Blocking here ensures it never opens or grows while waiting for the kill.
    if _is_aug_action and is_hedge and current_price > 0 and data_manager:
        _hg_sym = parse_position_key(position_key)[1] if parse_position_key(position_key) else ""
        _hg_is_long = position_key.endswith("_LONG")
        try:
            _, _hg_ind, _, _, _, _, _ = await data_manager.get_hot_state(_hg_sym)
            if isinstance(_hg_ind, dict):
                _hg_w1 = safe_fetch_float(_hg_ind.get('wt1_3m', 0), 0)
                _hg_w2 = safe_fetch_float(_hg_ind.get('wt2_3m', 0), 0)
                if _hg_w1 != 0 or _hg_w2 != 0:
                    _hg_blocked = (_hg_is_long and _hg_w1 <= _hg_w2) or (not _hg_is_long and _hg_w1 >= _hg_w2)
                    if _hg_blocked:
                        logger.critical(f"🚫 [HEDGE_WT3M_BLOCK] {position_key}: {'LONG' if _hg_is_long else 'SHORT'} hedge wt1_3m={_hg_w1:.1f} wt2_3m={_hg_w2:.1f} — WT3m AGAINST hedge direction. BLOCKED. action={action} reason={reason[:60]}")
                        return False, f"BLOCKED_HEDGE_WT3M_{_hg_w1:.1f}/{_hg_w2:.1f}"
        except Exception as _hg_e:
            logger.debug(f"[HEDGE_WT3M_BLOCK] indicator check failed for {position_key}: {_hg_e}")
    # ═══ BACKTEST_CHANGE_100-104: HARD ENTRY QUALITY GATE — NO BYPASS, NO EXCEPTIONS ═══
    # 2026-04-09 EXCEPTION: winner augments (gain ≥ MIN_GAIN) and pullback augments
    # (max_gain > current_gain AND gain ≥ 0.5×MIN_GAIN) bypass the LTF/HTF gates entirely.
    # Only the simple 3m/15m WT confirmation applies for those — no 1h LTF, no 4h/D HTF.
    # Per user directive: "AUGMENT orders >3% should NOT be filtered by anything except
    # simple wt 3m / 15m confirmation no lt at all".
    if _is_aug_action and not is_hedge and current_price > 0:
        _pk_parts = parse_position_key(position_key)
        _gate_symbol = _pk_parts[1] if _pk_parts else ""
        _gate_is_long = position_key.endswith("_LONG")
        _gate_is_short = position_key.endswith("_SHORT")
        _gate_ind = None
        if data_manager:
            try:
                _, _gate_ind, _, _, _, _, _ = await data_manager.get_hot_state(_gate_symbol)
            except Exception:
                pass
        if not _gate_ind and hasattr(trade_manager, 'data_manager') and trade_manager.data_manager:
            try:
                _, _gate_ind, _, _, _, _, _ = await trade_manager.data_manager.get_hot_state(_gate_symbol)
            except Exception:
                pass
        if _gate_ind and isinstance(_gate_ind, dict):
            # Determine if this is a "winner augment" (gain ≥ MIN_GAIN) or "pullback augment"
            # (in pullback AND gain ≥ 0.5×MIN_GAIN). Both bypass LTF/HTF requirements.
            _gate_pos = await tracker_manager.get_position(position_key)
            if not _gate_pos:
                _gate_pos = tracker_manager.positions_service.positions_by_account.get(account_key, {}).get(position_key) if hasattr(tracker_manager, 'positions_service') else None
            _gate_gain = safe_fetch_float(getattr(_gate_pos, 'gain', 0), 0)
            _gate_max = safe_fetch_float(getattr(_gate_pos, 'max_gain', 0), 0)
            _min_gain_cfg = safe_fetch_float(getattr(config, 'MIN_GAIN', 3.0), 3.0)
            _is_winner_aug = action in ('AUGMENT', 'QUICK_AUGMENT') and _gate_gain >= _min_gain_cfg
            _is_pullback_aug = action in ('AUGMENT', 'QUICK_AUGMENT') and _gate_gain >= 0.5 * _min_gain_cfg and (_gate_max - _gate_gain) >= 1.0
            _is_rz_entry = False
            # WAVETREND ALIGNMENT: require LTF (3m+15m+1h), use 4h/D as sizing discount not gate
            _gw1_3m = safe_fetch_float(_gate_ind.get('wt1_3m'), 0); _gw2_3m = safe_fetch_float(_gate_ind.get('wt2_3m'), 0)
            _gw1_15m = safe_fetch_float(_gate_ind.get('wt1_15m'), 0); _gw2_15m = safe_fetch_float(_gate_ind.get('wt2_15m'), 0)
            _gw1_1h = safe_fetch_float(_gate_ind.get('wt1_1h'), 0); _gw2_1h = safe_fetch_float(_gate_ind.get('wt2_1h'), 0)
            _gw1_4h = safe_fetch_float(_gate_ind.get('wt1_4h'), 0); _gw2_4h = safe_fetch_float(_gate_ind.get('wt2_4h'), 0)
            _gw1_D = safe_fetch_float(_gate_ind.get('wt1_D'), 0); _gw2_D = safe_fetch_float(_gate_ind.get('wt2_D'), 0)
            if _gate_is_long:
                _gwt_ltf = sum([_gw1_3m > _gw2_3m, _gw1_15m > _gw2_15m, _gw1_1h > _gw2_1h])
                _gwt_htf = sum([_gw1_4h > _gw2_4h, _gw1_D > _gw2_D])
                _wt_3m_aligned = _gw1_3m > _gw2_3m
                _wt_15m_aligned = _gw1_15m > _gw2_15m
            else:
                _gwt_ltf = sum([_gw1_3m < _gw2_3m, _gw1_15m < _gw2_15m, _gw1_1h < _gw2_1h])
                _gwt_htf = sum([_gw1_4h < _gw2_4h, _gw1_D < _gw2_D])
                _wt_3m_aligned = _gw1_3m < _gw2_3m
                _wt_15m_aligned = _gw1_15m < _gw2_15m
            _gwt_d = f"3m:{_gw1_3m:.0f}/{_gw2_3m:.0f} 15m:{_gw1_15m:.0f}/{_gw2_15m:.0f} 1h:{_gw1_1h:.0f}/{_gw2_1h:.0f} 4h:{_gw1_4h:.0f}/{_gw2_4h:.0f} D:{_gw1_D:.0f}/{_gw2_D:.0f}"
            if _is_pullback_aug or _is_winner_aug:
                # NO FALLING KNIFE: both winner and pullback augments REQUIRE simple
                # 3m + 15m WT confirmation. The pullback only relaxes the gain threshold
                # (1.5% vs 3%), it does NOT bypass WT alignment.
                # Per user directive: "longs: wt1_3m>wt2_3m and wt1_15m>wt2_15m. shorts v.v."
                _aug_tag = "PULLBACK_AUG" if _is_pullback_aug else "WINNER_AUG"
                if _wt_3m_aligned and _wt_15m_aligned:
                    logger.info(f"✅ [WT_GATE_BYPASS_{_aug_tag}] {position_key}: gain={_gate_gain:.2f}% (max={_gate_max:.2f}%) + 3m+15m WT aligned → bypassing LTF/HTF gates. {_gwt_d}")
                else:
                    logger.warning(f"🚫 [WT_3m15m_GATE] {position_key}: BLOCKED {_aug_tag} — 3m_aligned={_wt_3m_aligned} 15m_aligned={_wt_15m_aligned} (BOTH required, no falling-knife). {_gwt_d}")
                    return False, f"WT_3m15m_GATE_3m={_wt_3m_aligned}_15m={_wt_15m_aligned}"
            else:
                # RZ_BASELINE / RED_ZONE / 3-phase truck entries: bypass WT_LTF_GATE.
                # The bounce logic in wt_dc_delta._run_redzone already validates
                # HTF alignment (_htf_bull_ok / _htf_bear_ok) AND LTF velocity bounce
                # (_ltf_vel_bull / _ltf_vel_bear). Re-checking WT cross alignment here
                # would block 99% of legitimate pullback-bounce entries since the LTF
                # WT hasn't completed its cross yet at the bounce moment — that's the
                # whole point of trading the bounce.
                _reason_str = str(reason or "").upper()
                _is_rz_entry = (
                    _reason_str.startswith("RZ_")
                    or "RED_ZONE" in _reason_str
                    or "BASELINE_BOUNCE" in _reason_str
                    or "BREAKDOWN_TRUCK" in _reason_str
                    or "BOTTOM_HUGE" in _reason_str
                    or "REJECTION_OLD_REDZONE" in _reason_str
                    or "TRUCK_LOAD" in _reason_str
                )
                if _is_rz_entry:
                    logger.info(f"✅ [WT_GATE_BYPASS_RZ] {position_key}: RZ entry ({_reason_str[:40]}) — bypassing LTF gate (bounce logic already validated HTF+LTF velocity). {_gwt_d}")
                elif _gwt_ltf < 2:
                    logger.warning(f"🚫 [WT_LTF_GATE] {position_key}: BLOCKED — only {_gwt_ltf}/3 LTF WT aligned. Need 2. {_gwt_d}. action={action}")
                    return False, f"WT_LTF_GATE_{_gwt_ltf}/3"
                if not _is_rz_entry and _gwt_htf < 2:
                    _wt_discount = 0.5 if _gwt_htf == 1 else 0.3
                    qty = qty * _wt_discount
                    if override_qty: override_qty = override_qty * _wt_discount
                    logger.info(f"📉 [WT_HTF_DISCOUNT] {position_key}: {_gwt_htf}/2 HTF WT aligned → qty x{_wt_discount} (ltf={_gwt_ltf}/3). {_gwt_d}. action={action}")
            # ═══ HTF DIRECTION GATE (D + 4h + 1h + price-vs-SMA200D) ═══
            # Blocks entries against the higher-TF direction. Configurable via HTF_GATE_* switches.
            # Whitelist: RZ bounces (own HTF logic) and winner/pullback augments (own 3m+15m gate).
            if bool(getattr(config, 'HTF_DIRECTION_GATE_ENABLED', True)):
                _htf_apply_open = bool(getattr(config, 'HTF_GATE_APPLY_TO_OPEN', True))
                _htf_apply_aug = bool(getattr(config, 'HTF_GATE_APPLY_TO_AUGMENT', False))
                _htf_bypass_rz = bool(getattr(config, 'HTF_GATE_BYPASS_RZ', True))
                _is_aug_target = bool(_is_winner_aug or _is_pullback_aug)
                _is_open_target = not _is_aug_target
                _should_gate = (_is_open_target and _htf_apply_open) or (_is_aug_target and _htf_apply_aug)
                if _should_gate and not (_htf_bypass_rz and _is_rz_entry) and 'RATIO_RECOVERY' not in str(reason or '').upper():
                    _htf_pass, _htf_met, _htf_total, _htf_reason = check_htf_direction_gate(_gate_ind, _gate_is_long, current_price)
                    if not _htf_pass:
                        logger.warning(f"🚫 [HTF_DIRECTION_GATE] {position_key}: BLOCKED {action} ({reason[:60] if reason else ''}) — {_htf_reason}")
                        return False, f"HTF_DIRECTION_GATE_{_htf_met}/{_htf_total}"
                    else:
                        logger.info(f"✅ [HTF_DIRECTION_GATE] {position_key}: {_htf_reason}")
    if _is_aug_action and not is_hedge:
        _last_trade_ts = _hard_trade_guard.get(position_key, 0)
        _since = time.time() - _last_trade_ts
        if _since < _HARD_TRADE_GUARD_COOLDOWN:
            logger.critical(f"🚫🚫🚫 [HARD_TRADE_GUARD] {position_key}: BLOCKED — last trade {_since:.0f}s ago (need {_HARD_TRADE_GUARD_COOLDOWN}s). action={action} reason={reason}. NO BYPASS.")
            return False, f"BLOCKED_HARD_TRADE_GUARD_{_since:.0f}s"
    # ═══ UNIVERSAL POSITION GUARD — positions ALWAYS exist (never null/pop/delete) ═══
    # If positionAmt > min_qty → position is OPEN → NO open/reentry/hedge-open allowed
    if _is_aug_action:
        _fresh_pos = await tracker_manager.get_position(position_key)
        if not _fresh_pos:
            _fresh_pos = tracker_manager.positions_service.positions_by_account.get(account_key, {}).get(position_key) if hasattr(tracker_manager, 'positions_service') else None
        _fresh_amt = abs(safe_fetch_float(getattr(_fresh_pos, 'positionAmt', 0), 0)) if _fresh_pos else 0
        _fresh_val = _fresh_amt * current_price if current_price > 0 else 0
        _pos_symbol = parse_position_key(position_key)[1] if position_key else ""
        _min_qty = max(config.MIN_POSITION_SIZE / current_price, trade_manager.min_qty.get(_pos_symbol, 0.0) * 1.2) if current_price > 0 else 0
        _max_pos_val = float(getattr(config, 'START_POSITION_SIZE', 18.0)) * 12.0
        _pos_is_open = _fresh_amt > _min_qty
        # HARD BLOCK: No entry action on an already-open position — covers ALL entry action names
        _ENTRY_ACTIONS_ETW = {'OPEN', 'AUGMENT', 'REENTRY', 'REVERSE', 'REVERSE_AUGMENT', 'QUICK_OPEN', 'QUICK_AUGMENT', 'QUICK_HEDGE_OPEN', 'QUICK_HEDGE_AUGMENT', 'HEDGE_OPEN'}
        _action_upper = (action or '').upper()
        _is_entry = _action_upper in _ENTRY_ACTIONS_ETW or 'OPEN' in _action_upper or 'ENTRY' in _action_upper or 'HEDGE' in _action_upper or 'AUGMENT' in _action_upper
        _is_entry = _is_entry and 'CLOSE' not in _action_upper and 'REDUCE' not in _action_upper and 'KILL' not in _action_upper
        if _pos_is_open and _is_entry and _action_upper != 'AUGMENT' and _action_upper != 'QUICK_AUGMENT':
            logger.warning(f"🚫 [POSITION_ALREADY_OPEN] {position_key}: BLOCKED {action} — amt={_fresh_amt:.4f} > min={_min_qty:.4f} (val=${_fresh_val:.1f}). Position is OPEN. Use AUGMENT only.")
            return False, f"BLOCKED_POSITION_ALREADY_OPEN"
        # ATOMIC DOUBLE-OPEN GUARD: If position is CLOSED (amt=0) and another thread is already opening it, block
        if not _pos_is_open and _is_entry:
            _inflight_ts = _open_in_flight.get(position_key, 0)
            if time.time() - _inflight_ts < 60:
                logger.critical(f"🚫🚫 [DOUBLE_OPEN_BLOCK] {position_key}: BLOCKED {action} — another OPEN is in-flight (started {time.time() - _inflight_ts:.0f}s ago). RACE CONDITION PREVENTED.")
                return False, f"BLOCKED_DOUBLE_OPEN_IN_FLIGHT"
            _open_in_flight[position_key] = time.time()
        # HARD BLOCK: No augments beyond max position value
        # TEMPORARY SAFETY CAP — remove once multiple-opens bug is confirmed fixed
        if not is_hedge and _fresh_val > _max_pos_val:
            logger.warning(f"🚫 [MAX_SIZE_BLOCK_TEMP] {position_key}: BLOCKED {action} — position ${_fresh_val:.0f} exceeds TEMPORARY max ${_max_pos_val:.0f}. Remove cap once multiple-opens confirmed fixed.")
            return False, f"BLOCKED_MAX_SIZE_TEMP_{_fresh_val:.0f}"
    if 'OPEN' in action:
        if not is_hedge and is_open_pending(position_key):
            logger.warning(f"🛑 [OPEN_PENDING_BLOCK] {position_key}: Open already pending (cooldown {PENDING_OPEN_COOLDOWN}s). Rejecting duplicate.")
            return False, "BLOCKED_OPEN_PENDING"
        mark_open_pending(position_key)
    if 'WAIT' in reason and "FORCE" not in reason and "REENTRY" not in reason and "DC_BREAKOUT" not in reason and "RATIO_RECOVERY" not in reason and "BB_SQUEEZE_BREAKOUT" not in reason and not is_hedge:
        logger.warning(f"[WAIT_BLOCK] {position_key} {reason}: Strategy is in WAIT state.")
        return False, "BLOCKED_STRATEGY_WAIT"
    # === L/S RATIO ENFORCEMENT ===
    # RZ baseline / red zone / 3-phase truck entries are exempt — they're deliberate
    # strategy entries that read the market (bounce off baseline, BBs, DC) and should
    # fire even if they push the portfolio ratio out of bounds. The bounce logic in
    # wt_dc_delta._run_redzone already validates HTF alignment so these are with-flow.
    _ls_reason_upper = (reason or "").upper()
    _ls_is_rz = (
        _ls_reason_upper.startswith("RZ_")
        or "RED_ZONE" in _ls_reason_upper
        or "BASELINE_BOUNCE" in _ls_reason_upper
        or "BREAKDOWN_TRUCK" in _ls_reason_upper
        or "BOTTOM_HUGE" in _ls_reason_upper
        or "REJECTION_OLD_REDZONE" in _ls_reason_upper
        or "TRUCK_LOAD" in _ls_reason_upper
    )
    if getattr(config, "LS_RATIO_ENFORCE", False) and ("OPEN" in action or "AUGMENT" in action) and not is_hedge and "RATIO_RECOVERY" not in reason and "REENTRY" not in action.upper() and "REENTRY" not in reason.upper() and not _ls_is_rz:
        total_min_val = 50.0
        ratio, lv, sv = await get_ls_ratio(tracker_manager, account_key)
        total_val = lv + sv
        if total_val >= total_min_val:
            is_opening_long = position_key.endswith("_LONG")
            is_opening_short = position_key.endswith("_SHORT")
            open_val = qty * current_price if current_price > 0 else 0
            new_lv = lv + (open_val if is_opening_long else 0)
            new_sv = sv + (open_val if is_opening_short else 0)
            new_ratio = new_lv / new_sv if new_sv > 0 else 999.0
            hard_min = getattr(config, "LS_RATIO_HARD_MIN", 0.25)
            hard_max = getattr(config, "LS_RATIO_HARD_MAX", 4.0)
            soft_min = getattr(config, "LS_RATIO_MIN", 0.40)
            soft_max = getattr(config, "LS_RATIO_MAX", 2.50)
            # PnL-tightened dynamic gates: when per-side PnL diverges, compress the soft limits
            # so new entries on the losing side are blocked earlier. Added 2026-04-16.
            if bool(getattr(config, "RATIO_PNL_DYNAMIC_GATES_ENABLED", True)):
                _lavg, _savg, _lc_g, _sc_g, _pnl_d = compute_side_pnl(tracker_manager, account_key)
                _pnl_thr = float(getattr(config, "RATIO_PNL_DELTA_THRESHOLD", 3.0))
                if abs(_pnl_d) >= _pnl_thr and _lc_g > 0 and _sc_g > 0:
                    _tight_min = float(getattr(config, "RATIO_PNL_GATE_SOFT_MIN", 0.5))
                    _tight_max = float(getattr(config, "RATIO_PNL_GATE_SOFT_MAX", 2.0))
                    if _pnl_d > 0:
                        # Longs winning → tighten soft_min upward (block more shorts), widen soft_max (allow more longs)
                        soft_min = max(soft_min, _tight_min)
                    else:
                        # Shorts winning → tighten soft_max downward (block more longs), widen soft_min (allow more shorts)
                        soft_max = min(soft_max, _tight_max)
                    logger.debug(f"[LS_RATIO_PNL_TIGHTEN] {position_key}: pnl_d={_pnl_d:.2f}% (L_avg={_lavg:.2f}% S_avg={_savg:.2f}%) → soft=[{soft_min:.2f},{soft_max:.2f}]")
            _bear_mode = getattr(config, "BEAR_MARKET_MODE", False)
            _bull_mode = not _bear_mode and ratio < 0.5
            _noloss = account_key in getattr(config, 'STRICT_NO_LOSS_ACCOUNTS', [])
            _losing_longs = sum(1 for _pk, _p in tracker_manager.positions_service.positions_by_account.get(account_key, {}).items() if _pk.endswith('_LONG') and abs(safe_fetch_float(getattr(_p, 'positionAmt', 0), 0)) > 0.0001 and safe_fetch_float(getattr(_p, 'gain', 0), 0) < -0.5) if _noloss and _bear_mode and is_opening_short else 0
            _losing_shorts = sum(1 for _pk, _p in tracker_manager.positions_service.positions_by_account.get(account_key, {}).items() if _pk.endswith('_SHORT') and abs(safe_fetch_float(getattr(_p, 'positionAmt', 0), 0)) > 0.0001 and safe_fetch_float(getattr(_p, 'gain', 0), 0) < -0.5) if _noloss and _bull_mode and is_opening_long else 0
            _market_override = (_bear_mode and is_opening_short and _losing_longs >= 3) or (_bull_mode and is_opening_long and _losing_shorts >= 3)
            if _market_override:
                logger.info(f"📈 [MARKET_OVERRIDE] {position_key}: {'BEAR' if _bear_mode else 'BULL'} mode + {_losing_longs or _losing_shorts} stuck losers → ratio limits SUSPENDED for {'SHORT' if is_opening_short else 'LONG'} open (ratio={ratio:.2f})")
            blocked = False
            if not _market_override:
                if is_opening_short and new_ratio < hard_min:
                    logger.critical(f"\U0001f6d1 [LS_RATIO_HARD_BLOCK] {position_key}: Blocking SHORT open. Ratio would be {new_ratio:.3f} (hard min {hard_min}). L=${lv:.0f} S=${sv:.0f}")
                    blocked = True
                elif is_opening_long and new_ratio > hard_max:
                    logger.critical(f"\U0001f6d1 [LS_RATIO_HARD_BLOCK] {position_key}: Blocking LONG open. Ratio would be {new_ratio:.3f} (hard max {hard_max}). L=${lv:.0f} S=${sv:.0f}")
                    blocked = True
                elif is_opening_short and new_ratio < soft_min and ratio < soft_min:
                    now_ts = time.time()
                    log_key = f"ls_soft_{account_key}"
                    if now_ts - _ls_ratio_last_log.get(log_key, 0) > getattr(config, "LS_RATIO_LOG_INTERVAL", 60):
                        logger.warning(f"\U0001f6a7 [LS_RATIO_SOFT_BLOCK] {position_key}: Blocking SHORT open. Ratio {ratio:.3f} < {soft_min}. L=${lv:.0f} S=${sv:.0f}")
                        _ls_ratio_last_log[log_key] = now_ts
                    blocked = True
                elif is_opening_long and new_ratio > soft_max and ratio > soft_max:
                    now_ts = time.time()
                    log_key = f"ls_soft_{account_key}"
                    if now_ts - _ls_ratio_last_log.get(log_key, 0) > getattr(config, "LS_RATIO_LOG_INTERVAL", 60):
                        logger.warning(f"\U0001f6a7 [LS_RATIO_SOFT_BLOCK] {position_key}: Blocking LONG open. Ratio {ratio:.3f} > {soft_max}. L=${lv:.0f} S=${sv:.0f}")
                        _ls_ratio_last_log[log_key] = now_ts
                    blocked = True
            if blocked:
                return False, f"BLOCKED_LS_RATIO_{ratio:.3f}"
    # === L/S RATIO EXIT ENFORCEMENT: block reduces that worsen hard-limit breaches ===
    if getattr(config, "LS_RATIO_ENFORCE", False) and action in ('REDUCE', 'PROFIT_TAKE') and not is_hedge and "EMERGENCY" not in reason.upper() and "LIQUIDATION" not in reason.upper() and "STOP" not in reason.upper():
        ratio, lv, sv = await get_ls_ratio(tracker_manager, account_key)
        hard_max = getattr(config, "LS_RATIO_HARD_MAX", 4.0)
        hard_min = getattr(config, "LS_RATIO_HARD_MIN", 0.25)
        is_closing_short = position_key.endswith("_SHORT")
        is_closing_long = position_key.endswith("_LONG")
        if is_closing_short and ratio > hard_max and sv > 0:
            logger.warning(f"🚧 [LS_RATIO_EXIT_BLOCK] {position_key}: Blocking REDUCE SHORT — ratio {ratio:.3f} already > hard_max {hard_max}. Reducing shorts worsens imbalance.")
            return False, f"BLOCKED_LS_RATIO_EXIT_WORSENS_{ratio:.3f}"
        if is_closing_long and ratio < hard_min and lv > 0:
            logger.warning(f"🚧 [LS_RATIO_EXIT_BLOCK] {position_key}: Blocking REDUCE LONG — ratio {ratio:.3f} already < hard_min {hard_min}. Reducing longs worsens imbalance.")
            return False, f"BLOCKED_LS_RATIO_EXIT_WORSENS_{ratio:.3f}"
    if is_hedge_account(config, account_key) and ('CLOSE' in action or 'REDUCE' in action) and not is_hedge:
        async with tracker_manager._hedges_lock:
            has_active_hedge = any(h.get('losing_position_key') == position_key for h in tracker_manager.active_hedges)
        if has_active_hedge and "HEDGE" not in reason.upper() and "ENGINE" not in reason.upper() and "GAIN" not in reason.upper() and "PROFIT" not in reason.upper() and "TP" not in reason.upper() and "DC_BREACH" not in reason.upper():
            if "GLOBAL_HARD_STOP" not in reason.upper():
                logger.warning(f"🛡️[HEDGE_MODE_BLOCK] {position_key}: Blocking {action} ({reason}) - Must be managed by HedgeEngine.")
                return False, "BLOCKED_BY_HEDGE_MODE"
    service = tracker_manager.positions_service
    fresh_position = await tracker_manager.get_position(position_key)
    ak, symbol, position_side = parse_position_key(position_key)
    is_long = (position_side == 'LONG')
    pos_min_qty = max(config.MIN_POSITION_SIZE / current_price, trade_manager.min_qty.get(symbol, 0.0) * 1.2)
    
    if is_strict_no_loss_account(config, account_key) and ('CLOSE' in action or 'REDUCE' in action):
        fresh_pos = await tracker_manager.get_position(position_key)
        if fresh_pos:
            _entry_px = safe_fetch_float(getattr(fresh_pos, 'entry_price', 0), 0) or safe_fetch_float(getattr(fresh_pos, 'entry_price', 0), 0)
            if _entry_px > 0 and current_price > 0:
                _real_gain = ((current_price - _entry_px) / _entry_px * 100) if is_long else (((_entry_px - current_price) / _entry_px) * 100)
            else:
                _real_gain = fresh_pos.gain
            if _entry_px <= 0 and not is_hedge:
                logger.critical(f"🛑[STRICT_NO_LOSS_BLOCK][{account_key}] {position_key}: Blocking {action} ({reason}) — entry_price=0, gain unreliable (cached={fresh_pos.gain:.2f}%). REFUSING CLOSE.")
                await tracker_manager.set_trade_cooldown(position_key, duration=300)
                return False, "BLOCKED_NO_ENTRY_PRICE"
            if _real_gain < -0.01:
                bypass_strict = 'LIQUIDATION' in reason.upper() or 'GAIN_EROSION' in reason.upper() or (is_hedge and is_hedge_account(config, account_key))
                if not bypass_strict and not is_hedge:
                    logger.critical(f"🛑[STRICT_NO_LOSS_BLOCK][{account_key}] {position_key}: Blocking {action} ({reason}) at REAL loss ({_real_gain:.2f}%, cached={fresh_pos.gain:.2f}%). NEVER SELL AT A LOSS.")
                    # ═══ OBLIGATORY HEDGE — SACRED RULE (re-enabled 2026-04-17) ═══
                    # User: "Every time any short (or long v.v.) has wt1_3m > wt2_3m, a hedge HAS TO
                    # BE TAKEN OUT. THIS IS THE RULE AND HAS BEEN FOREVER."
                    # History: previously killed 2026-03-30 after 15,378 rogue opens (3 OBLIGATORY_HEDGE
                    # loops without tracker consultation). Cascade fix already in place at execute_dual_hedge
                    # lines 5244-5261 (hedge-of-hedge block, already-hedged check, in-flight dedup).
                    # NOW: multi-TF WT gate added — wt_1m + wt_15m + wt_1h must confirm against position.
                    # NEVER DISABLED via `if False:` — tuning via config switches only.
                    _obl_enabled = bool(getattr(config, 'OBLIGATORY_HEDGE_ENABLED', True))
                    _hedge_min_loss = float(getattr(config, 'OBLIGATORY_HEDGE_MIN_LOSS_PCT', -0.25))
                    _hedge_pct = float(getattr(config, 'OBLIGATORY_HEDGE_PCT', 1.0))
                    _wt_tfs_required = int(getattr(config, 'OBLIGATORY_HEDGE_WT_TFS_REQUIRED', 2))
                    if _obl_enabled and hedge_engine and _real_gain < _hedge_min_loss:
                        # Per-TF enables (2026-04-17 60d test on 8 bleeding inf shorts):
                        # 3m+1h min2 (both must agree) = 47% precision, +359% PnL proxy (BEST).
                        # K filter adds nothing (-19% PnL vs no K). Default 3m+1h enabled, 1m/15m off.
                        _use_1m = bool(getattr(config, 'OBLIGATORY_HEDGE_WT_USE_1M', False))
                        _use_3m = bool(getattr(config, 'OBLIGATORY_HEDGE_WT_USE_3M', True))
                        _use_15m = bool(getattr(config, 'OBLIGATORY_HEDGE_WT_USE_15M', False))
                        _use_1h = bool(getattr(config, 'OBLIGATORY_HEDGE_WT_USE_1H', True))
                        _oh_ind = indicators or {}
                        _wt_against_count = 0
                        _tfs_enabled = 0
                        if _use_1m:
                            _tfs_enabled += 1
                            _w1 = safe_fetch_float(_oh_ind.get('wt1_1m'), 0); _w2 = safe_fetch_float(_oh_ind.get('wt2_1m'), 0)
                            _wt_against_count += int((is_long and _w1 < _w2) or (not is_long and _w1 > _w2))
                        if _use_3m:
                            _tfs_enabled += 1
                            _w1 = safe_fetch_float(_oh_ind.get('wt1_3m'), 0); _w2 = safe_fetch_float(_oh_ind.get('wt2_3m'), 0)
                            _wt_against_count += int((is_long and _w1 < _w2) or (not is_long and _w1 > _w2))
                        if _use_15m:
                            _tfs_enabled += 1
                            _w1 = safe_fetch_float(_oh_ind.get('wt1_15m'), 0); _w2 = safe_fetch_float(_oh_ind.get('wt2_15m'), 0)
                            _wt_against_count += int((is_long and _w1 < _w2) or (not is_long and _w1 > _w2))
                        if _use_1h:
                            _tfs_enabled += 1
                            _w1 = safe_fetch_float(_oh_ind.get('wt1_1h'), 0); _w2 = safe_fetch_float(_oh_ind.get('wt2_1h'), 0)
                            _wt_against_count += int((is_long and _w1 < _w2) or (not is_long and _w1 > _w2))
                        if _wt_against_count >= _wt_tfs_required and _tfs_enabled > 0:
                            async with tracker_manager._hedges_lock:
                                _already_hedged = any(h.get('losing_position_key') == position_key for h in tracker_manager.active_hedges if isinstance(h, dict))
                            if not _already_hedged:
                                _losing_val = abs(fresh_pos.positionAmt) * current_price * _hedge_pct
                                logger.warning(f"[OBLIGATORY_HEDGE] {position_key}: gain={_real_gain:.2f}% wt_against={_wt_against_count}/4 (1m/3m/15m/1h) — opening {_hedge_pct*100:.0f}% hedge (${_losing_val:.2f})")
                                asyncio.create_task(hedge_engine.execute_dual_hedge(account_key=account_key, losing_position_key=position_key, losing_symbol=symbol, losing_side='LONG' if is_long else 'SHORT', losing_value_usd=_losing_val, dry_run=False))
                            else:
                                logger.info(f"[OBLIGATORY_HEDGE_EXISTS] {position_key}: gain={_real_gain:.2f}% wt_against={_wt_against_count}/4 — already hedged")
                        else:
                            logger.info(f"[OBLIGATORY_HEDGE_SKIP_WT] {position_key}: gain={_real_gain:.2f}% wt_against={_wt_against_count}/4 < {_wt_tfs_required} — WT not confirming reversal yet")
                    await tracker_manager.set_trade_cooldown(position_key, duration=300)
                    return False, "BLOCKED_BY_STRICT_NO_LOSS"
            # BACKTEST_CHANGE_108: NO-LOSS NATURAL EXIT — also block reduces below min profit %
            _noloss_min_pct = getattr(config, 'NOLOSS_MIN_PROFIT_PCT', 0.50)
            if _noloss_min_pct > 0 and _real_gain < _noloss_min_pct and _real_gain >= -0.01 and not is_hedge:
                bypass_noloss = 'LIQUIDATION' in reason.upper() or 'EMERGENCY' in reason.upper() or 'GAIN_PROTECTION' in reason.upper() or 'GAIN_EROSION' in reason.upper()
                if not bypass_noloss:
                    logger.info(f"[NOLOSS_MIN_BLOCK][{account_key}] {position_key}: Blocking {action} ({reason}) — gain={_real_gain:.2f}% < min={_noloss_min_pct}%. Wait for natural TP.")
                    return False, f"BLOCKED_NOLOSS_MIN_{_real_gain:.2f}pct"

    is_force_dc = 'FORCE_DC' in reason.upper() or 'DC_BREAKOUT' in reason.upper() or 'BB_SQUEEZE_BREAKOUT' in reason.upper()
    _is_ratio_recovery = 'RATIO_RECOVERY' in reason.upper()
    _is_reentry = 'REENTRY' in action.upper() or 'REENTRY' in reason.upper()
    _is_wr_signal = 'WR_PULLBACK' in reason.upper() or 'LR_SHORTTOP' in reason.upper() or 'WR_LR_' in reason.upper()
    if getattr(config, 'BASIS_CONDITION', False) and ('OPEN' in action or 'AUGMENT' in action) and not is_hedge and not is_force_dc and not _is_ratio_recovery and not _is_reentry and not _is_wr_signal:
        if data_manager:
            _, ind, _, _, _, _, _ = await data_manager.get_hot_state(symbol)
            b15 = safe_fetch_float(ind.get('dc_basis_15m'), 0)
            b1h = safe_fetch_float(ind.get('dc_basis_1h'), 0)
            b4h = safe_fetch_float(ind.get('dc_basis_4h'), 0)
            bd = safe_fetch_float(ind.get('dc_basis_D'), 0)
            k15 = safe_fetch_float(ind.get('stoch_k_15m'), 50)
            d15 = safe_fetch_float(ind.get('stoch_d_15m'), 50)
            if b15 > 0 and b1h > 0 and b4h > 0 and bd > 0:
                if is_long:
                    if current_price < b15 or current_price < b1h or current_price < b4h or current_price < bd:
                        logger.warning(f"🛑 [BASIS_BOYCOTT] {position_key}: Price {current_price} BELOW basis. Blocking entry.")
                        return False, "BASIS_BOYCOTT_LONG"
                    if k15 < d15:
                        logger.warning(f"🛑 [STOCH_BOYCOTT] {position_key}: k_15m {k15} < d_15m {d15}. Blocking entry.")
                        return False, "STOCH_BOYCOTT_LONG"
                    s1h = safe_fetch_float(ind.get("sma_200_1h"), 0)
                    s4h = safe_fetch_float(ind.get("sma_200_4h"), 0)
                    if (s1h > 0 and current_price < s1h) or (s4h > 0 and current_price < s4h):
                        logger.warning(f"🛑 [SMA200_BOYCOTT] {position_key}: Price {current_price} BELOW sma200 (1h={s1h:.4f} 4h={s4h:.4f}). Blocking LONG entry.")
                        return False, "SMA200_BOYCOTT_LONG"
                else:
                    if current_price > b15 or current_price > b1h or current_price > b4h or current_price > bd:
                        logger.warning(f"🛑 [BASIS_BOYCOTT] {position_key}: Price {current_price} ABOVE basis. Blocking entry.")
                        return False, "BASIS_BOYCOTT_SHORT"
                    if k15 > d15:
                        logger.warning(f"🛑 [STOCH_BOYCOTT] {position_key}: k_15m {k15} > d_15m {d15}. Blocking entry.")
                        return False, "STOCH_BOYCOTT_SHORT"
                    s1h = safe_fetch_float(ind.get("sma_200_1h"), 0)
                    s4h = safe_fetch_float(ind.get("sma_200_4h"), 0)
                    if (s1h > 0 and current_price > s1h) or (s4h > 0 and current_price > s4h):
                        logger.warning(f"🛑 [SMA200_BOYCOTT] {position_key}: Price {current_price} ABOVE sma200 (1h={s1h:.4f} 4h={s4h:.4f}). Blocking SHORT entry.")
                        return False, "SMA200_BOYCOTT_SHORT"

    # SCALP MOMENTUM BOYCOTT — DEAD 2026-04-09
    # The legacy SCALP_MODE-gated 1m K direction boycott was the "useless" old
