async def priority_exit_scan_loop(trade_manager, account_key: str, stop_event: asyncio.Event, redis_manager, tracker_manager: TrackerManager, order_queue, data_manager: FastDataManager, hedge_engine: HedgeEngine):
    logger.info(f"🛡️ [EXIT_PRIORITY][{account_key}] STARTED")
    last_summary = time.time()
    count = 0
    while not stop_event.is_set():
        try:
            async with tracker_manager._exit_candidates_lock:
                active_keys = list(k for k in tracker_manager.exit_candidates.keys() if k.startswith(account_key))
                if tracker_manager.positions_service:
                    positions = tracker_manager.positions_service.positions_by_account.get(account_key, {})
                    for k, pos in positions.items():
                        if not k.startswith(account_key): continue
                        amt = abs(safe_fetch_float(getattr(pos, 'positionAmt', 0.0), 0.0))
                        if amt > 0.0:
                            mark_price = safe_fetch_float(getattr(pos, 'mark_price', 0.0), 0.0)
                            val = amt * mark_price
                            start_size = safe_fetch_float(getattr(trade_manager.config, 'START_POSITION_SIZE', 45.0), 45.0)
                            is_tradeable = k in tracker_manager.tradeable_keys
                            if val >= start_size or not is_tradeable:
                                active_keys.append(k)
            if not active_keys:
                if time.time() - last_summary > 60:
                    logger.info(f"🛡️ [EXIT_PRIORITY][{account_key}] Idle (0 active positions).")
                    last_summary = time.time()
                await asyncio.sleep(3.0)
                continue
            import random
            random.shuffle(active_keys)
            BATCH_SIZE = 10 
            for i in range(0, len(active_keys), BATCH_SIZE):
                batch = active_keys[i:i+BATCH_SIZE]
                tasks = []
                for key in batch:
                    if await tracker_manager.is_processing(key): continue
                    tasks.append(check_exit_candidates_for_account( trade_manager, account_key, redis_manager, tracker_manager, order_queue, data_manager, hedge_engine, position_keys=[key] ))
                    count += 1
                if tasks:
                    await asyncio.gather(*tasks)
                await asyncio.sleep(0.2)
            if time.time() - last_summary > 20:
                logger.info(f"🛡️ [EXIT_PRIORITY][{account_key}] Cycle OK. Checked {count} keys. Active: {len(active_keys)}")
                count = 0
                last_summary = time.time()
            await asyncio.sleep(3.0)  # Was 1.0 — 3s still catches exits within 5s, saves CPU
        except Exception as e:
            logger.error(f"❌ [EXIT_PRIO] Error: {e}")
            await asyncio.sleep(5.0)

async def quick_exit_monitor_loop(trade_manager, account_key: str, stop_event: asyncio.Event, redis_manager, tracker_manager: TrackerManager, order_queue, data_manager: FastDataManager, hedge_engine: HedgeEngine):
    logger.info(f"🛡️ [EXIT_MAINT][{account_key}] STARTED")
    while not stop_event.is_set():
        try:
            await tracker_manager._get_tradeable_keys_cached()
            await tracker_manager.sync_position_keys(account_key)
            async with tracker_manager._exit_candidates_lock:
                all_exits = list(k for k in tracker_manager.exit_candidates.keys() if k.startswith(account_key))
            all_exits.sort(key=lambda k: tracker_manager.last_check_times.get(k, 0.0))
            for key in all_exits:
                if await tracker_manager.is_processing(key): continue
                await check_exit_candidates_for_account( trade_manager, account_key, redis_manager, tracker_manager, order_queue, data_manager, hedge_engine, position_keys=[key] )
                await asyncio.sleep(0.2)
            await asyncio.sleep(6.0)
        except Exception as e:
            logger.error(f"❌ [EXIT_MAINT] Error: {e}")
            await asyncio.sleep(5.0)

async def quick_entry_monitor_loop(trade_manager, account_key: str, stop_event: asyncio.Event, redis_manager, tracker_manager: TrackerManager, order_queue, data_manager: FastDataManager, hedge_engine: HedgeEngine):
    logger.info(f"🔭 [ENTRY_STREAM][{account_key}] STARTED")
    sem = asyncio.Semaphore(30)
    last_summary = time.time()
    processed_count = 0

    async def safe_check(key):
        async with sem:
            if key not in tracker_manager.tradeable_keys: 
                return
            else: await check_entry_candidates_for_account(trade_manager, account_key, redis_manager, tracker_manager, order_queue, data_manager, hedge_engine, position_keys=[key])
    while not stop_event.is_set():
        try:
            universe = list(tracker_manager.get_tradeable_position_keys_for(account_key))
            universe.sort()
            async with tracker_manager._exit_candidates_lock:
                active = set(tracker_manager.exit_candidates.keys())
            candidates = [k for k in universe if k not in active and k.startswith(account_key)]
            valid_candidates = []
            start_size = safe_fetch_float(getattr(trade_manager.config, 'START_POSITION_SIZE', 45.0), 45.0)
            for k in candidates:
                pos = tracker_manager.positions_service.positions_by_account.get(account_key, {}).get(k)
                if pos:
                    amt = abs(safe_fetch_float(getattr(pos, 'positionAmt', 0.0), 0.0))
                    price = safe_fetch_float(getattr(pos, 'mark_price', 0.0), 0.0)
                    if (amt * price) >= start_size:
                        continue 
                valid_candidates.append(k)
            if not candidates: 
                await asyncio.sleep(2.0); continue
            import random
            random.shuffle(candidates)
            BATCH_SIZE = 50
            for i in range(0, len(candidates), BATCH_SIZE):
                batch = candidates[i:i+BATCH_SIZE]
                tasks = [asyncio.create_task(safe_check(k)) for k in batch]
                await asyncio.gather(*tasks)
                processed_count += len(batch)
                await asyncio.sleep(30)
            if time.time() - last_summary > 60:
                logger.info(f"🔭 [ENTRY_STREAM][{account_key}] Running. Checked {processed_count} candidates in last 60s.")
                processed_count = 0
                last_summary = time.time()
        except Exception as e:
            logger.error(f"❌ [ENTRY_STREAM] Error: {e}")
            await asyncio.sleep(5.0)

async def bulk_entry_scan_loop(trade_manager, account_key: str, stop_event: asyncio.Event, redis_manager, tracker_manager: TrackerManager, order_queue, data_manager: FastDataManager, hedge_engine: HedgeEngine):
    logger.info(f"🚜 [ENTRY_BULK][{account_key}] STARTED")
    while not stop_event.is_set():
        try:
            await tracker_manager.sync_universe(account_key)
            await tracker_manager.sync_position_keys(account_key)
            # Universe = tradeable_position_keys ∪ reentry-file keys ∪ tracker positions (amt=0 still watched).
            # User directive 2026-04-17: manually-closed positions must stay under reentry watch as long
            # as their key remains in tradeable_keys — reentry.json / tracker are the memory that survives
            # a close; without this union they vanished from the scan once positionAmt hit 0.
            universe = set(tracker_manager.get_tradeable_position_keys_for(account_key))
            _prefix = f"{account_key}:"
            _reentry_data = getattr(tracker_manager, 'reentry_data', None) or {}
            for _rk in _reentry_data.keys():
                if isinstance(_rk, str) and _rk.startswith(_prefix): universe.add(_rk)
            async with tracker_manager._entry_candidates_lock:
                for _ek in tracker_manager.entry_candidates.keys():
                    if isinstance(_ek, str) and _ek.startswith(_prefix): universe.add(_ek)
            try:
                _tk_global = getattr(tracker_manager, 'tradeable_keys', None) or set()
                for _gk in _tk_global:
                    if isinstance(_gk, str) and _gk.startswith(_prefix): universe.add(_gk)
            except Exception: pass
            universe = sorted(universe)
            count = 0
            for key in universe:
                async with tracker_manager._exit_candidates_lock:
                    if key in tracker_manager.exit_candidates: continue
                last_check = tracker_manager.get_last_check_time(key)
                if (time.time() - last_check) < 30.0: continue
                if key not in tracker_manager.tradeable_keys:
                    continue
                else:
                    await check_entry_candidates_for_account( trade_manager, account_key, redis_manager, tracker_manager, order_queue, data_manager, hedge_engine, position_keys=[key] )
                count += 1
                await asyncio.sleep(0.1)
            if count > 0:
                logger.info(f"🚜 [ENTRY_BULK][{account_key}] Sweep complete. Checked {count} keys (universe={len(universe)}, includes reentry+tradeable).")
            await asyncio.sleep(40.0)
        except Exception as e:
            logger.error(f"❌ [ENTRY_BULK] Error: {e}", exc_info=True)
            await asyncio.sleep(10.0)

async def pair_flatten_stuck_loop(trade_manager, account_key: str, stop_event: asyncio.Event, redis_manager, tracker_manager: TrackerManager, order_queue, data_manager: FastDataManager, hedge_engine: HedgeEngine):
    """Periodic scan: find hedged pairs (LONG+SHORT same symbol) that are STUCK
    (net P&L ~$0, sitting idle, both legs open ≥ 1h) and CLOSE BOTH legs together
    to free up the symbol slot and capital.

    User directive 2026-04-09: 'we need to alleviate the system of pairs that are
    not doing anything ... no more positions can be opened because stupid pairs are
    moving up and down — needs closure of all stuck positions'.

    The losing leg's loss is bounded by the WINNING leg's profit (net ≈ 0). Closing
    both at once realises ≈ $0 net change to account equity but frees up the slot.
    """
    logger.info(f"🤝 [PAIR_FLATTEN][{account_key}] STARTED")
    while not stop_event.is_set():
        try:
            await asyncio.sleep(180)  # every 3 minutes
            positions = tracker_manager.positions_service.positions_by_account.get(account_key, {}) if hasattr(tracker_manager, 'positions_service') and tracker_manager.positions_service else {}
            if not positions:
                continue
            # Build symbol → {side: (key, pos)} map
            sym_map = {}
            for k, p in positions.items():
                if not k.startswith(f"{account_key}:"):
                    continue
                amt = abs(safe_fetch_float(getattr(p, 'positionAmt', 0), 0))
                if amt <= 0:
                    continue
                try:
                    _, sym, side = parse_position_key(k)
                except Exception:
                    continue
                sym_map.setdefault(sym, {})[side] = (k, p)
            stuck = []
            _now = datetime.now(timezone.utc)
            for sym, sides in sym_map.items():
                if 'LONG' not in sides or 'SHORT' not in sides:
                    continue
                long_key, long_pos = sides['LONG']
                short_key, short_pos = sides['SHORT']
                long_amt = abs(safe_fetch_float(getattr(long_pos, 'positionAmt', 0), 0))
                short_amt = abs(safe_fetch_float(getattr(short_pos, 'positionAmt', 0), 0))
                if long_amt <= 0 or short_amt <= 0:
                    continue
                long_mark = safe_fetch_float(getattr(long_pos, 'mark_price', 0), 0)
                short_mark = safe_fetch_float(getattr(short_pos, 'mark_price', 0), 0)
                long_gain = safe_fetch_float(getattr(long_pos, 'gain', 0), 0)
                short_gain = safe_fetch_float(getattr(short_pos, 'gain', 0), 0)
                long_val = long_amt * long_mark
                short_val = short_amt * short_mark
                long_pnl_usd = long_val * long_gain / 100.0
                short_pnl_usd = short_val * short_gain / 100.0
                net_pnl_usd = long_pnl_usd + short_pnl_usd
                total_val = long_val + short_val
                if total_val < 5.0:
                    continue  # too small to bother
                # Pair must be at least 1h old (older of the two legs)
                long_opened = safe_datetime(getattr(long_pos, 'opened_at', None))
                short_opened = safe_datetime(getattr(short_pos, 'opened_at', None))
                pair_age_min = float('inf')
                if long_opened:
                    pair_age_min = min(pair_age_min, (_now - long_opened).total_seconds() / 60)
                if short_opened:
                    pair_age_min = min(pair_age_min, (_now - short_opened).total_seconds() / 60)
                if pair_age_min < 60:
                    continue
                # Net PnL near 0: |net| < max($3, 1% of total value)
                pnl_threshold = max(3.0, total_val * 0.01)
                if abs(net_pnl_usd) > pnl_threshold:
                    continue
                stuck.append((sym, long_key, short_key, long_pos, short_pos, long_val, short_val, net_pnl_usd, total_val, long_amt, short_amt))
            if not stuck:
                continue
            logger.warning(f"🤝 [PAIR_FLATTEN][{account_key}] Found {len(stuck)} stuck pairs (net ~$0, age ≥1h) — closing both legs")
            for sym, long_key, short_key, long_pos, short_pos, long_val, short_val, net_pnl, total_val, long_amt, short_amt in stuck:
                logger.warning(f"🤝 [PAIR_FLATTEN] {account_key}:{sym}: LONG=${long_val:.1f}({long_amt:.4f}) SHORT=${short_val:.1f}({short_amt:.4f}) net=${net_pnl:+.2f} → flattening")
                try:
                    cur_px, _ = await get_current_price(sym)
                except Exception:
                    cur_px = safe_fetch_float(getattr(long_pos, 'mark_price', 0), 0)
                _flatten_reason = f"PAIR_FLATTEN_NET_${net_pnl:+.2f}"
                # Close LONG
                try:
                    await execute_trade_wrapper(
                        trade_manager, tracker_manager, hedge_engine,
                        account_key, long_key, long_amt, 'QUICK_CLOSE',
                        cur_px, long_amt, _flatten_reason,
                        is_hedge=False, data_manager=data_manager
                    )
                except Exception as e:
                    logger.error(f"[PAIR_FLATTEN] {long_key} close failed: {e}")
                await asyncio.sleep(1.5)
                # Close SHORT
                try:
                    await execute_trade_wrapper(
                        trade_manager, tracker_manager, hedge_engine,
                        account_key, short_key, short_amt, 'QUICK_CLOSE',
                        cur_px, short_amt, _flatten_reason,
                        is_hedge=False, data_manager=data_manager
                    )
                except Exception as e:
                    logger.error(f"[PAIR_FLATTEN] {short_key} close failed: {e}")
                await asyncio.sleep(2.0)
        except asyncio.CancelledError:
            break
        except Exception as e:
            logger.error(f"❌ [PAIR_FLATTEN][{account_key}] Error: {e}", exc_info=True)
            await asyncio.sleep(30)


